import { LegacyAny } from '@/types/legacy';
// ============================================================================
// MCP Addon Manager Tests
// ============================================================================

import { MCPAddonManager } from_ '../MCPAddonManager';
import type { MCPServerConfig, MCPAddonState } from '@/types/addons';

describe('MCPAddonManager', () => {
  let manager: MCPAddonManager;

  beforeEach(() => {
    manager = new MCPAddonManager();
  });

  describe('Constructor', () => {
    it('should initialize with default addon state', () => {
      const state = manager.getState();
      
      expect(state.addon).toBeDefined();
      expect(state.addon.id).toBe('mcp-server');
      expect(state.addon.name).toBe('MCP Server Integration');
      expect(state.addon.enabled).toBe(false);
      expect(state.addon.permissions).toBeDefined();
      expect(state.addon.permissions.length).toBeGreaterThan(0);
      expect(state.isLoading).toBe(false);
      expect(state.error).toBeNull();
    });

    it('should initialize with custom addon partial', () => {
      const customAddon = {
        id: 'custom-mcp',
        name: 'Custom MCP Server',
        enabled: true,
      };
      
      const customManager = new MCPAddonManager(customAddon);
      const state = customManager.getState();
      
      expect(state.addon.id).toBe('custom-mcp');
      expect(state.addon.name).toBe('Custom MCP Server');
      expect(state.addon.enabled).toBe(true);
    });
  });

  describe('State Management', () => {
    it('should notify listeners when state changes', () => {
      const listener = jest.fn();
      manager.subscribe(listener);
      
      // Initial state should trigger listener
      expect(listener).toHaveBeenCalledWith(manager.getState());
      
      // State change should trigger listener
      manager['setState']({ ...manager.getState(), isLoading: true });
      expect(listener).toHaveBeenCalledTimes(2);
    });

    it('should unsubscribe listeners correctly', () => {
      const listener = jest.fn();
      const unsubscribe = manager.subscribe(listener);
      
      unsubscribe();
      manager['setState']({ ...manager.getState(), isLoading: true });
      
      // Listener should not be called after unsubscribe
      expect(listener).toHaveBeenCalledTimes(1);
    });
  });

  describe('Toggle Addon', () => {
    it('should enable addon when disabled', async () => {
      const state = manager.getState();
      expect(state.addon.enabled).toBe(false);
      
      await manager.toggleAddon(true);
      const updatedState = manager.getState();
      
      expect(updatedState.addon.enabled).toBe(true);
      expect(updatedState.isLoading).toBe(false);
    });

    it('should disable addon when enabled', async () => {
      // First enable the addon
      await manager.toggleAddon(true);
      
      const state = manager.getState();
      expect(state.addon.enabled).toBe(true);
      
      await manager.toggleAddon(false);
      const updatedState = manager.getState();
      
      expect(updatedState.addon.enabled).toBe(false);
      expect(updatedState.isLoading).toBe(false);
    });

    it('should handle errors during toggle', async () => {
      // Mock the delay function to throw an error
      jest.spyOn(manager as LegacyAny, 'delay').mockRejectedValue(new Error('Test error'));
      
      await expect(manager.toggleAddon(true)).rejects.toThrow('Test error');
      
      const state = manager.getState();
      expect(state.error).toBe('Test error');
      expect(state.isLoading).toBe(false);
    });
  });

  describe('Server Management', () => {
    const mockServerConfig: Omit<MCPServerConfig, 'id'> = {
      name: 'Test Server',
      endpoint: 'https://api.example.com/mcp',
      timeout: 30000,
      maxRetries: 3,
      enabled: true,
      status: 'disconnected',
      capabilities: ['text-generation'],
    };

    describe('Add Server', () => {
      it('should add a new server successfully', async () => {
        const initialServers = manager.getState().servers;
        expect(initialServers).toHaveLength(0);
        
        await manager.addServer(mockServerConfig);
        const state = manager.getState();
        
        expect(state.servers).toHaveLength(1);
        expect(state.servers[0].name).toBe('Test Server');
        expect(state.servers[0].endpoint).toBe('https://api.example.com/mcp');
        expect(state.servers[0].id).toBeDefined();
      });

      it('should test server connection when adding', async () => {
        const testSpy = jest.spyOn(manager, 'testServer');
        
        await manager.addServer(mockServerConfig);
        
        expect(testSpy).toHaveBeenCalledWith(expect.any(String));
      });

      it('should handle errors when adding server', async () => {
        jest.spyOn(manager as LegacyAny, 'delay').mockRejectedValue(new Error('Add error'));
        
        await expect(manager.addServer(mockServerConfig)).rejects.toThrow('Add error');
        
        const state = manager.getState();
        expect(state.error).toBe('Add error');
      });
    });

    describe('Update Server', () => {
      it('should update existing server', async () => {
        await manager.addServer(mockServerConfig);
        const server = manager.getState().servers[0];
        
        await manager.updateServer(server.id, { 
          name: 'Updated Server',
          timeout: 60000,
        });
        
        const state = manager.getState();
        expect(state.servers[0].name).toBe('Updated Server');
        expect(state.servers[0].timeout).toBe(60000);
      });

      it('should handle errors when updating server', async () => {
        await manager.addServer(mockServerConfig);
        const server = manager.getState().servers[0];
        
        jest.spyOn(manager as LegacyAny, 'delay').mockRejectedValue(new Error('Update error'));
        
        await expect(manager.updateServer(server.id, { name: 'Test' }))
          .rejects.toThrow('Update error');
      });
    });

    describe('Remove Server', () => {
      it('should remove server successfully', async () => {
        await manager.addServer(mockServerConfig);
        const server = manager.getState().servers[0];
        
        await manager.removeServer(server.id);
        
        const state = manager.getState();
        expect(state.servers).toHaveLength(0);
      });

      it('should clear selected server when removing it', async () => {
        await manager.addServer(mockServerConfig);
        const server = manager.getState().servers[0];
        
        manager.setSelectedServer(server.id);
        expect(manager.getState().selectedServer).toBe(server.id);
        
        await manager.removeServer(server.id);
        
        expect(manager.getState().selectedServer).toBeNull();
      });

      it('should handle errors when removing server', async () => {
        await manager.addServer(mockServerConfig);
        const server = manager.getState().servers[0];
        
        jest.spyOn(manager as LegacyAny, 'delay').mockRejectedValue(new Error('Remove error'));
        
        await expect(manager.removeServer(server.id)).rejects.toThrow('Remove error');
      });
    });

    describe('Test Server', () => {
      it('should test server connection', async () => {
        await manager.addServer(mockServerConfig);
        const server = manager.getState().servers[0];
        
        await manager.testServer(server.id);
        
        const state = manager.getState();
        expect(state.testResults).toHaveLength(1);
        expect(state.testResults[0].serverId).toBe(server.id);
      });

      it('should handle server test errors', async () => {
        jest.spyOn(manager as LegacyAny, 'delay').mockRejectedValue(new Error('Test error'));
        
        await expect(manager.testServer('non-existent')).rejects.toThrow('Test error');
      });
    });
  });

  describe('Utility Methods', () => {
    const mockServerConfig: Omit<MCPServerConfig, 'id'> = {
      name: 'Test Server',
      endpoint: 'https://api.example.com/mcp',
      timeout: 30000,
      maxRetries: 3,
      enabled: true,
      status: 'connected',
      capabilities: ['text-generation'],
    };

    beforeEach(async () => {
      await manager.addServer(mockServerConfig);
    });

    it('should get server by id', () => {
      const server = manager.getServerById(manager.getState().servers[0].id);
      
      expect(server).toBeDefined();
      expect(server?.name).toBe('Test Server');
    });

    it('should return null for non-existent server', () => {
      const server = manager.getServerById('non-existent');
      
      expect(server).toBeNull();
    });

    it('should check if server exists', () => {
      const exists = manager.hasServer(manager.getState().servers[0].id);
      
      expect(exists).toBe(true);
      
      const notExists = manager.hasServer('non-existent');
      expect(notExists).toBe(false);
    });

    it('should get connected servers', () => {
      const connected = manager.getConnectedServers();
      
      expect(connected).toHaveLength(1);
      expect(connected[0].status).toBe('connected');
    });
  });

  describe('Configuration', () => {
    it('should update config successfully', async () => {
      await manager.updateConfig({ defaultTimeout: 60000 });
      
      const state = manager.getState();
      expect(state.addon.config.defaultTimeout).toBe(60000);
    });

    it('should handle config update errors', async () => {
      jest.spyOn(manager as LegacyAny, 'delay').mockRejectedValue(new Error('Config error'));
      
      await expect(manager.updateConfig({})).rejects.toThrow('Config error');
    });
  });
});

/**
 * VirtualShotList - Virtualized shot list for performance with large projects
 * 
 * Uses virtual scrolling to render only visible shots, improving performance
 * with projects containing 100+ shots.
 * 
 * Requirements: 10.2
 */
import { LegacyAny } from '@/types/legacy';


import React, { useRef, useState, useCallback } from 'react';
import { _Button } from_ './ui/button';
import { Badge } from './ui/badge';
import { CheckCircle, AlertCircle, Circle } from 'lucide-react';
import type { Shot } from '../types/projectDashboard';
import { calculateVisibleItems } from '../utils/performanceOptimizations';

// ============================================================================
// Constants
// ============================================================================

const ITEM_HEIGHT = 100; // Height of each shot item in pixels
const OVERSCAN = 5; // Number of items to render outside viewport

// ============================================================================
// Component Props
// ============================================================================

export interface VirtualShotListProps {
  shots: Shot[];
  selectedShotId: string | null;
  onShotSelect: (shot: Shot) => void;
  getPromptIndicator: (shot: Shot) => {
    icon: React.ComponentType<LegacyAny>;
    color: string;
    label: string;
    variant: 'default' | 'secondary' | 'outline' | 'destructive';
  };
  containerHeight: number;
  className?: string;
}

// ============================================================================
// Component
// ============================================================================

export const VirtualShotList: React.FC<VirtualShotListProps> = ({
  shots,
  selectedShotId,
  onShotSelect,
  getPromptIndicator,
  containerHeight,
  className = '',
}) => {
  // ============================================================================
  // State
  // ============================================================================

  const [scrollTop, setScrollTop] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);

  // ============================================================================
  // Handlers
  // ============================================================================

  const handleScroll = useCallback((e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop);
  }, []);

  // ============================================================================
  // Virtual Scrolling Calculation
  // ============================================================================

  const { visibleItems, totalHeight, offsetY } = React.useMemo(() => {
    return calculateVisibleItems(
      shots,
      scrollTop,
      containerHeight,
      ITEM_HEIGHT,
      OVERSCAN
    );
  }, [shots, scrollTop, containerHeight]);

  // ============================================================================
  // Render
  // ============================================================================

  return (
    <div
      ref={containerRef}
      className={`virtual-shot-list overflow-auto ${className}`}
      style={{ height: containerHeight }}
      onScroll={handleScroll}
      role="list"
      aria-label="Shot list"
    >
      {/* Spacer for total height */}
      <div style={{ height: totalHeight, position: 'relative' }}>
        {/* Visible items container */}
        <div
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            transform: `translateY(${offsetY}px)`,
          }}
        >
          {visibleItems.map((shot) => {
            const indicator = getPromptIndicator(shot);
            const Icon = indicator.icon;
            const isSelected = selectedShotId === shot.id;

            return (
              <div
                key={shot.id}
                style={{ height: ITEM_HEIGHT }}
                className="px-2 py-1"
              >
                <Button
                  variant={isSelected ? 'default' : 'outline'}
                  className={`w-full justify-start text-left h-full py-3 px-4 ${
                    isSelected ? 'ring-2 ring-primary' : ''
                  }`}
                  onClick={() => onShotSelect(shot)}
                  role="listitem"
                  aria-label={`Shot ${shot.id.slice(0, 8)}, ${indicator.label}, ${shot.startTime} to ${shot.startTime + shot.duration} seconds`}
                  aria-pressed={isSelected}
                >
                  <div className="flex items-start gap-3 w-full">
                    {/* Completion Indicator */}
                    <Icon className={`h-5 w-5 mt-0.5 flex-shrink-0 ${indicator.color}`} aria-hidden="true" />
                    
                    {/* Shot Info */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center justify-between gap-2 mb-1">
                        <span className="font-medium text-sm truncate">
                          Shot {shot.id.slice(0, 8)}
                        </span>
                        <Badge variant={indicator.variant} className="text-xs" aria-hidden="true">
                          {indicator.label}
                        </Badge>
                      </div>
                      
                      {/* Shot Metadata */}
                      <div className="text-xs text-muted-foreground space-y-0.5">
                        <div>
                          Time: {shot.startTime}s - {shot.startTime + shot.duration}s
                        </div>
                        {shot.metadata.cameraAngle && (
                          <div>Camera: {shot.metadata.cameraAngle}</div>
                        )}
                      </div>
                      
                      {/* Prompt Preview */}
                      {shot.prompt && (
                        <div className="text-xs text-muted-foreground mt-2 line-clamp-2" aria-label="Prompt preview">
                          {shot.prompt}
                        </div>
                      )}
                    </div>
                  </div>
                </Button>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default VirtualShotList;

import { LegacyAny } from '@/types/legacy';
import React from 'react';
import { render, screen, fireEvent _} from '@testing-library/react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { CharacterCard } from '../CharacterCard';
import type { Character } from '@/types/character';

// Mock character data
const createMockCharacter = (overrides?: Partial<Character>): Character => ({
  character_id: 'char-123',
  name: 'John Doe',
  creation_method: 'wizard',
  creation_timestamp: '2024-01-15T10:30:00Z',
  version: '1.0',
  visual_identity: {
    hair_color: 'brown',
    hair_style: 'short',
    hair_length: 'short',
    eye_color: 'blue',
    eye_shape: 'round',
    skin_tone: 'fair',
    facial_structure: 'oval',
    distinctive_features: ['scar on left cheek'],
    age_range: '25-35',
    height: '6ft',
    build: 'athletic',
    posture: 'upright',
    clothing_style: 'casual',
    color_palette: ['blue', 'gray'],
  },
  personality: {
    traits: ['brave', 'loyal'],
    values: ['justice', 'family'],
    fears: ['failure'],
    desires: ['success'],
    flaws: ['stubborn'],
    strengths: ['determined'],
    temperament: 'calm',
    communication_style: 'direct',
  },
  background: {
    origin: 'New York',
    occupation: 'Detective',
    education: 'Police Academy',
    family: 'Married with two kids',
    significant_events: ['Solved major case'],
    current_situation: 'Working on new case',
  },
  relationships: [],
  role: {
    archetype: 'Hero',
    narrative_function: 'Protagonist',
    character_arc: 'Redemption',
  },
  ...overrides,
});

describe('CharacterCard', () => {
  describe('Basic Rendering', () => {
    it('should render character name', () => {
      const character = createMockCharacter();
      render(<CharacterCard character={character} />);
      
      expect(screen.getByText('John Doe')).toBeInTheDocument();
    });

    it('should render character archetype', () => {
      const character = createMockCharacter();
      render(<CharacterCard character={character} />);
      
      expect(screen.getByText('Hero')).toBeInTheDocument();
    });

    it('should render age range', () => {
      const character = createMockCharacter();
      render(<CharacterCard character={character} />);
      
      expect(screen.getByText('25-35')).toBeInTheDocument();
    });

    it('should render formatted creation date', () => {
      const character = createMockCharacter();
      render(<CharacterCard character={character} />);
      
      // Date should be formatted as "Jan 15, 2024"
      expect(screen.getByText(/Jan 15, 2024/)).toBeInTheDocument();
    });

    it('should handle missing age range gracefully', () => {
      const character = createMockCharacter({
        visual_identity: {
          ...createMockCharacter().visual_identity,
          age_range: '',
        },
      });
      render(<CharacterCard character={character} />);
      
      expect(screen.getByText('Not specified')).toBeInTheDocument();
    });
  });

  describe('Thumbnail Display', () => {
    it('should display thumbnail image when thumbnail_url is provided', () => {
      const character = {
        ...createMockCharacter(),
        thumbnail_url: 'https://example.com/thumbnail.jpg',
      } as LegacyAny;
      render(<CharacterCard character={character} />);
      
      const img = screen.getByAltText('John Doe thumbnail');
      expect(img).toBeInTheDocument();
      expect(img).toHaveAttribute('src', 'https://example.com/thumbnail.jpg');
    });

    it('should display placeholder when no thumbnail_url is provided', () => {
      const character = createMockCharacter();
      render(<CharacterCard character={character} />);
      
      // Should have placeholder with User icon
      const placeholder = document.querySelector('.character-card__thumbnail-placeholder');
      expect(placeholder).toBeInTheDocument();
    });

    it('should handle image load error gracefully', () => {
      const character = {
        ...createMockCharacter(),
        thumbnail_url: 'https://example.com/broken.jpg',
      } as LegacyAny;
      render(<CharacterCard character={character} />);
      
      const img = screen.getByAltText('John Doe thumbnail');
      
      // Simulate image load error
      fireEvent.error(img);
      
      // Should show placeholder after error
      const placeholder = document.querySelector('.character-card__thumbnail-placeholder');
      expect(placeholder).toBeInTheDocument();
    });
  });

  describe('Click Handling', () => {
    it('should call onClick when card is clicked', () => {
      const character = createMockCharacter();
      const handleClick = vi.fn();
      render(<CharacterCard character={character} onClick={handleClick} />);
      
      const card = document.querySelector('.character-card');
      fireEvent.click(card!);
      
      expect(handleClick).toHaveBeenCalledTimes(1);
    });

    it('should handle Enter key press', () => {
      const character = createMockCharacter();
      const handleClick = vi.fn();
      render(<CharacterCard character={character} onClick={handleClick} />);
      
      const card = document.querySelector('.character-card');
      fireEvent.keyDown(card!, { key: 'Enter' });
      
      expect(handleClick).toHaveBeenCalledTimes(1);
    });

    it('should handle Space key press', () => {
      const character = createMockCharacter();
      const handleClick = vi.fn();
      render(<CharacterCard character={character} onClick={handleClick} />);
      
      const card = document.querySelector('.character-card');
      fireEvent.keyDown(card!, { key: ' ' });
      
      expect(handleClick).toHaveBeenCalledTimes(1);
    });

    it('should not call onClick when card is not clickable', () => {
      const character = createMockCharacter();
      const handleClick = vi.fn();
      render(<CharacterCard character={character} />);
      
      const card = document.querySelector('.character-card');
      fireEvent.click(card!);
      
      expect(handleClick).not.toHaveBeenCalled();
    });
  });

  describe('Selection Mode', () => {
    it('should render checkbox when selectable is true', () => {
      const character = createMockCharacter();
      render(<CharacterCard character={character} selectable={true} />);
      
      const checkbox = screen.getByRole('checkbox', { name: 'Select John Doe' });
      expect(checkbox).toBeInTheDocument();
    });

    it('should not render checkbox when selectable is false', () => {
      const character = createMockCharacter();
      render(<CharacterCard character={character} selectable={false} />);
      
      const checkbox = screen.queryByRole('checkbox');
      expect(checkbox).not.toBeInTheDocument();
    });

    it('should reflect selected state in checkbox', () => {
      const character = createMockCharacter();
      render(
        <CharacterCard
          character={character}
          selectable={true}
          selected={true}
        />
      );
      
      const checkbox = screen.getByLabelText('Select John Doe') as HTMLInputElement;
      expect(checkbox.checked).toBe(true);
    });

    it('should call onSelect when checkbox is changed', () => {
      const character = createMockCharacter();
      const handleSelect = vi.fn();
      render(
        <CharacterCard
          character={character}
          selectable={true}
          selected={false}
          onSelect={handleSelect}
        />
      );
      
      const checkbox = screen.getByLabelText('Select John Doe');
      fireEvent.click(checkbox);
      
      expect(handleSelect).toHaveBeenCalledWith(true);
    });

    it('should toggle selection when card is clicked in selectable mode', () => {
      const character = createMockCharacter();
      const handleSelect = vi.fn();
      render(
        <CharacterCard
          character={character}
          selectable={true}
          selected={false}
          onSelect={handleSelect}
        />
      );
      
      const card = document.querySelector('.character-card');
      fireEvent.click(card!);
      
      expect(handleSelect).toHaveBeenCalledWith(true);
    });

    it('should apply selected styling when selected', () => {
      const character = createMockCharacter();
      render(
        <CharacterCard
          character={character}
          selectable={true}
          selected={true}
        />
      );
      
      const card = document.querySelector('.character-card');
      expect(card).toHaveClass('character-card--selected');
    });

    it('should stop propagation when checkbox is clicked', () => {
      const character = createMockCharacter();
      const handleSelect = vi.fn();
      const handleClick = vi.fn();
      render(
        <CharacterCard
          character={character}
          selectable={true}
          onClick={handleClick}
          onSelect={handleSelect}
        />
      );
      
      const checkbox = screen.getByLabelText('Select John Doe');
      fireEvent.click(checkbox);
      
      // onSelect should be called, but onClick should not
      expect(handleSelect).toHaveBeenCalled();
      expect(handleClick).not.toHaveBeenCalled();
    });
  });

  describe('Action Buttons', () => {
    it('should render edit button when showActions is true and onEdit is provided', () => {
      const character = createMockCharacter();
      const handleEdit = vi.fn();
      render(
        <CharacterCard
          character={character}
          showActions={true}
          onEdit={handleEdit}
        />
      );
      
      const editButton = screen.getByLabelText('Edit John Doe');
      expect(editButton).toBeInTheDocument();
    });

    it('should render delete button when showActions is true and onDelete is provided', () => {
      const character = createMockCharacter();
      const handleDelete = vi.fn();
      render(
        <CharacterCard
          character={character}
          showActions={true}
          onDelete={handleDelete}
        />
      );
      
      const deleteButton = screen.getByLabelText('Delete John Doe');
      expect(deleteButton).toBeInTheDocument();
    });

    it('should not render action buttons when showActions is false', () => {
      const character = createMockCharacter();
      render(
        <CharacterCard
          character={character}
          showActions={false}
          onEdit={vi.fn()}
          onDelete={vi.fn()}
        />
      );
      
      const actions = document.querySelector('.character-card__actions');
      expect(actions).not.toBeInTheDocument();
    });

    it('should call onEdit when edit button is clicked', () => {
      const character = createMockCharacter();
      const handleEdit = vi.fn();
      render(
        <CharacterCard
          character={character}
          showActions={true}
          onEdit={handleEdit}
        />
      );
      
      const editButton = screen.getByLabelText('Edit John Doe');
      fireEvent.click(editButton);
      
      expect(handleEdit).toHaveBeenCalledTimes(1);
    });

    it('should call onDelete when delete button is clicked', () => {
      const character = createMockCharacter();
      const handleDelete = vi.fn();
      render(
        <CharacterCard
          character={character}
          showActions={true}
          onDelete={handleDelete}
        />
      );
      
      const deleteButton = screen.getByLabelText('Delete John Doe');
      fireEvent.click(deleteButton);
      
      expect(handleDelete).toHaveBeenCalledTimes(1);
    });

    it('should stop propagation when action buttons are clicked', () => {
      const character = createMockCharacter();
      const handleEdit = vi.fn();
      const handleClick = vi.fn();
      render(
        <CharacterCard
          character={character}
          showActions={true}
          onClick={handleClick}
          onEdit={handleEdit}
        />
      );
      
      const editButton = screen.getByLabelText('Edit John Doe');
      fireEvent.click(editButton);
      
      // onEdit should be called, but onClick should not
      expect(handleEdit).toHaveBeenCalled();
      expect(handleClick).not.toHaveBeenCalled();
    });
  });

  describe('Loading State', () => {
    it('should render loading skeleton when loading is true', () => {
      const character = createMockCharacter();
      render(<CharacterCard character={character} loading={true} />);
      
      const skeleton = document.querySelector('.character-card__skeleton');
      expect(skeleton).toBeInTheDocument();
    });

    it('should not render character content when loading', () => {
      const character = createMockCharacter();
      render(<CharacterCard character={character} loading={true} />);
      
      expect(screen.queryByText('John Doe')).not.toBeInTheDocument();
    });

