    <Dialog open={true} onOpenChange={onClose}>
      <DialogContent className="max-w-4xl p-0 overflow-hidden bg-background">
        <div className="flex h-[80vh]">
          <div className="flex-1 bg-black flex items-center justify-center p-4">
