                        variant="ghost"
                        size="sm"
                        onClick={() => handleDeleteLocation(location.location_id)}
                        className="h-8 px-2 text-gray-600 hover:text-red-600"
                      >
                        <TrashIcon className="w-4 h-4" />
                      </Button>
                    </div>
                  </div>
                ))
              )}
