          </div>
        </DialogContent>
      </Dialog>

      {/* Edit Modal */}
      {editingLocation && (
        <LocationEditModal
          location={editingLocation}
          onSave={handleSaveLocation}
          onCancel={() => {
            setEditingLocation(null);
            setShowEditModal(false);
          }}
          isOpen={showEditModal}
        />
      )}
    </>
  );
}

interface LocationEditModalProps {
  location: Location;
  onSave: (location: Location) => void;
  onCancel: () => void;
  isOpen: boolean;
}

function LocationEditModal({ location, onSave, onCancel, isOpen }: LocationEditModalProps) {
  const [editedLocation, setEditedLocation] = useState<Location>(location);
  const [newTag, setNewTag] = useState('');

  const handleUpdateMetadata = (updates: Partial<typeof location.metadata>) => {
    setEditedLocation(prev => ({
      ...prev,
      metadata: { ...prev.metadata, ...updates }
    }));
  };

  const handleAddTag = () => {
    const currentTags = editedLocation.metadata?.genre_tags || [];
    if (newTag.trim() && !currentTags.includes(newTag.trim())) {
      handleUpdateMetadata({
        genre_tags: [...currentTags, newTag.trim()]
      });
      setNewTag('');
    }
  };

  const handleRemoveTag = (tagToRemove: string) => {
    const currentTags = editedLocation.metadata?.genre_tags || [];
    handleUpdateMetadata({
      genre_tags: currentTags.filter(t => t !== tagToRemove)
    });
  };

  return (
    <Dialog open={isOpen} onOpenChange={onCancel}>
      <DialogContent className="max-w-2xl bg-white p-0 overflow-hidden">
        <DialogHeader className="p-6 bg-gray-900 text-white">
          <DialogTitle className="text-xl">
            {location.name ? `Edit Location: ${location.name}` : 'New Location'}
          </DialogTitle>
        </DialogHeader>

        <div className="p-6 space-y-6 max-h-[70vh] overflow-y-auto">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-sm font-medium text-gray-700">Location Name</label>
              <Input
                value={editedLocation.name}
                onChange={(e) => setEditedLocation({ ...editedLocation, name: e.target.value })}
                placeholder="Ex: Whispering Forest"
              />
            </div>
            <div className="space-y-2">
              <label className="text-sm font-medium text-gray-700">Type</label>
              <Select
                value={editedLocation.location_type}
                onValueChange={(val: LegacyAny) => setEditedLocation({ ...editedLocation, location_type: val })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="interior">Interior</SelectItem>
                  <SelectItem value="exterior">Exterior</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-gray-700">Short Description</label>
            <Textarea
              value={editedLocation.metadata?.description || ''}
              onChange={(e) => handleUpdateMetadata({ description: e.target.value })}
              placeholder="Describe this location..."
              className="min-h-[100px]"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-sm font-medium text-gray-700">Atmosphere</label>
              <Input
                value={editedLocation.metadata?.atmosphere || ''}
                onChange={(e) => handleUpdateMetadata({ atmosphere: e.target.value })}
                placeholder="Ex: Dark and spooky"
              />
            </div>
            <div className="space-y-2">
              <label className="text-sm font-medium text-gray-700">Importance</label>
              <Select
                value={editedLocation.metadata?.importance || 'medium'}
                onValueChange={(val: LegacyAny) => handleUpdateMetadata({ importance: val })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="high">High</SelectItem>
                  <SelectItem value="medium">Medium</SelectItem>
                  <SelectItem value="low">Low</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-gray-700">Address / Location</label>
            <Input
              value={editedLocation.metadata?.address || ''}
              onChange={(e) => handleUpdateMetadata({ address: e.target.value })}
              placeholder="Ex: South of the village"
            />
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-gray-700">Tags</label>
            <div className="flex gap-2 mb-2">
              <Input
                value={newTag}
                onChange={(e) => setNewTag(e.target.value)}
                placeholder="Add a tag..."
                onKeyDown={(e) => e.key === 'Enter' && handleAddTag()}
              />
              <Button onClick={handleAddTag} type="button">Add</Button>
            </div>
            <div className="flex flex-wrap gap-2">
              {(editedLocation.metadata?.genre_tags || []).map(tag => (
                <Badge key={tag} className="flex items-center gap-1">
                  {tag}
                  <XIcon
                    className="w-3 h-3 cursor-pointer hover:text-red-200"
                    onClick={() => handleRemoveTag(tag)}
                  />
                </Badge>
              ))}
            </div>
          </div>
        </div>

        <div className="p-6 border-t flex justify-end gap-3 bg-gray-50">
          <Button variant="outline" onClick={onCancel}>Cancel</Button>
          <Button onClick={() => onSave(editedLocation)} className="bg-blue-600 hover:bg-blue-700 text-white">
            <SaveIcon className="w-4 h-4 mr-2" />
            Save Location
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

/**
 * Pre-built Transition Effects
 * Ready-to-use transition components for common use cases
 */
import { LegacyAny } from '@/types/legacy';


im_port React, { CSSProperties, useCallback, useRef, useState } from 'react';
import {
  TransitionConfig,
  FadeTransitionConfig,
  SlideTransitionConfig,
  ZoomTransitionConfig,
  WipeTransitionConfig,
  GlitchTransitionConfig,
  GPUMode,
  PerformanceTier,
} from '../../services/transitions';
import { useTransition } from '../../hooks/useTransition';
import { TransitionWrapper, TransitionProgressBar, TransitionMetricsDisplay } from './TransitionWrapper';

// ============================================
// Fade Transition
// ============================================

export interface FadeTransitionProps {
  /** Child content */
  children: React.ReactNode;
  
  /** Fade type */
  fadeType?: 'black' | 'white' | 'cross' | 'transparent';
  
  /** Duration in milliseconds */
  duration?: number;
  
  /** Whether auto-triggers on children change */
  autoTrigger?: boolean;
  
  /** Current content key (triggers transition when changed) */
  contentKey?: string;
  
  /** Easing function */
  easing?: 'linear' | 'easeIn' | 'easeOut' | 'easeInOut' | 'elastic' | 'bounce';
  
  /** GPU mode */
  gpuMode?: GPUMode;
  
  /** Performance tier */
  performanceTier?: PerformanceTier;
  
  /** Callback when transition starts */
  onStart?: () => void;
  
  /** Callback when transition completes */
  onComplete?: () => void;
}

export const FadeTransition: React.FC<FadeTransitionProps> = ({
  children,
  fadeType = 'cross',
  duration = 500,
  autoTrigger = false,
  contentKey,
  easing = 'easeInOut',
  gpuMode = 'auto',
  performanceTier = 'high',
  onStart,
  onComplete,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [_key, setKey] = useState(contentKey || 'initial');
  const [progress, setProgress] = useState(0);
  const [metrics, setMetrics] = useState<LegacyAny>(null);

  const config: FadeTransitionConfig = {
    type: 'fade',
    fadeType,
    duration,
    easing,
    gpuMode,
    performanceTier,
    onStart: () => {
      setProgress(0);
      onStart?.();
    },
    onUpdate: (p) => setProgress(p),
    onComplete: () => {
      setProgress(1);
      setMetrics({ totalTime: duration }); // Simplified metrics
      onComplete?.();
    },
  };

  const { start, cancel } = useTransition(canvasRef, config);

  // Trigger transition when key changes
  React.useEffect(() => {
    if (autoTrigger && contentKey !== undefined) {
      setKey(contentKey);
      start(config);
    }
  }, [contentKey, autoTrigger, start]);

  return (
    <div style={{ position: 'relative', width: '100%', height: '100%' }}>
      <TransitionWrapper
        config={config}
        canvasRef={canvasRef}
        trigger={key}
        autoTrigger={autoTrigger}
        onTransitionStart={onStart}
        onTransitionComplete={onComplete}
        onProgressUpdate={setProgress}
      >
        <div key={key} style={{ width: '100%', height: '100%' }}>
          {children}
        </div>
      </TransitionWrapper>
      {progress > 0 && progress < 1 && (
        <TransitionProgressBar progress={progress} />
      )}
    </div>
  );
};

