              </div>
              <div className="flex gap-2 mt-2">
                <Input
                  value={newFear}
                  onChange={(e) => setNewFear(e.target.value)}
                  placeholder="Add INHIBITOR..."
                  onKeyPress={(e) => e.key === 'Enter' && handleAddItem('fears', newFear, setNewFear)}
