/**
 * FFmpeg Render Service
 *
 * Converts a Sequence Editor timeline into a rendered video file using FFmpeg.
 */
import { LegacyAny } from '@/types/legacy';


import type {
    Shot,
    Layer,
    MediaLayerData,
    _AudioLayerData,
    _TextLayerData,
    _TransitionLayerData,
    VideoMask,
    VideoEffects,
    RichTextStyle,
} from '../../sequence-editor/types';

impo_rt type {
    _ExportSettings,
    _ProgressCallback,
    _FilterGraph,
    FilterDefinition,
    _ExportQueueItem,
    _Resolution,
    VideoFormat,
    ExportResponse,
} from './FFmpegTypes';

import { electronFFmpegBridge } from './ElectronFFmpegBridge';

// =============================================================================
// Types
// =============================================================================

export interface RenderJob {
    id: string;
    shots: Shot[];
    settings: ExportSettings;
    outputPath: string;
    status: 'queued' | 'preparing' | 'rendering' | 'encoding' | 'completed' | 'failed' | 'cancelled';
    progress: number;
    currentStage: string;
    error?: string;
    startedAt?: number;
    completedAt?: number;
}

export interface FilterChainNode {
    label: string;
    filter: string;
    inputs: string[];
    outputs: string[];
}

export interface CompositorLayer {
    shotIndex: number;
    layerIndex: number;
    layer: Layer;
    inputLabel: string;
    startTimeGlobal: number; // absolute start in the timeline (seconds)
    endTimeGlobal: number;
}

export interface RenderProgress {
    jobId: string;
    stage: 'preparing' | 'compositing' | 'encoding' | 'audio-mix' | 'finalizing';
    progress: number; // 0-100
    message: string;
    fps?: number;
    timeElapsed: number;
    timeRemaining?: number;
}

// =============================================================================
// FFmpeg Render Service
// =============================================================================

export class FFmpegRenderService {
    private renderQueue: Map<string, RenderJob> = new Map();
    private isProcessing = false;

    private progressListeners: Map<string, ((p: RenderProgress) => void)[]> = new Map();

    // Build state
    private currentInputArgs: string[] = [];
    private currentInputIdx = 0;
    private currentFilterParts: string[] = [];

    // ---------------------------------------------------------------------------
    // Public API
    // ---------------------------------------------------------------------------

    async queueRender(
        shots: Shot[],
        settings: ExportSettings,
        outputPath: string,
    ): Promise<string> {
        const jobId = `render-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`;

        const job: RenderJob = {
            id: jobId,
            shots,
            settings,
            outputPath,
            status: 'queued',
            progress: 0,
            currentStage: 'Queued',
        };

        this.renderQueue.set(jobId, job);
        this.processQueue();
        return jobId;
    }

    onProgress(jobId: string, listener: (p: RenderProgress) => void): () => void {
        if (!this.progressListeners.has(jobId)) {
            this.progressListeners.set(jobId, []);
        }
        this.progressListeners.get(jobId)!.push(listener);

        return () => {
            const listeners = this.progressListeners.get(jobId);
            if (listeners) {
                const idx = listeners.indexOf(listener);
                if (idx !== -1) listeners.splice(idx, 1);
            }
        };
    }

    cancelRender(jobId: string): void {
        const job = this.renderQueue.get(jobId);
        if (job && job.status !== 'completed' && job.status !== 'failed') {
            job.status = 'cancelled';
            job.currentStage = 'Cancelled';
        }
    }

    getRenderStatus(jobId: string): RenderJob | undefined {
        return this.renderQueue.get(jobId);
    }

    // ---------------------------------------------------------------------------
    // Internal render pipeline
    // ---------------------------------------------------------------------------

    private async processQueue(): Promise<void> {
        if (this.isProcessing) return;
        this.isProcessing = true;

        try {
            for (const [, job] of this.renderQueue) {
                if (job.status === 'queued') {
                    await this.executeRender(job);
                }
            }
        } finally {
            this.isProcessing = false;
        }
    }

    private async executeRender(job: RenderJob): Promise<void> {
        const startTime = Date.now();
        job.startedAt = startTime;

        try {
            this.updateJob(job, 'preparing', 5, 'Analysing timeline...');
            const compositorLayers = this.flattenTimeline(job.shots, job.settings.fps);

            this.updateJob(job, 'preparing', 15, 'Building filtergraph...');
            const { filterGraphStr, inputArgs, outputMapArgs } =
                this.buildComplexFiltergraph(compositorLayers, job.settings);

            this.updateJob(job, 'rendering', 20, 'Rendering video...');
            await this.runFFmpeg(inputArgs, filterGraphStr, outputMapArgs, job);

            job.status = 'completed';
            job.progress = 100;
            job.currentStage = 'Done';
            job.completedAt = Date.now();

            this.emitProgress(job.id, {
                jobId: job.id,
                stage: 'finalizing',
                progress: 100,
                message: 'Render complete!',
                timeElapsed: (Date.now() - startTime) / 1000,
            });
        } catch (err: LegacyAny) {
            job.status = 'failed';
            job.error = err.message ?? String(err);
            job.currentStage = 'Error';

            this.emitProgress(job.id, {
                jobId: job.id,
                stage: 'finalizing',
                progress: job.progress,
                message: `Error: ${job.error}`,
                timeElapsed: (Date.now() - startTime) / 1000,
            });
        }
    }

    private flattenTimeline(shots: Shot[], fps: number): CompositorLayer[] {
        const layers: CompositorLayer[] = [];
        let inputCounter = 0;

        for (let si = 0; si < shots.length; si++) {
            const shot = shots[si];
            const shotStartSec = shot.startTime / fps;

            for (let li = 0; li < shot.layers.length; li++) {
                const layer = shot.layers[li];
                if (layer.hidden) continue;

                layers.push({
                    shotIndex: si,
                    layerIndex: li,
                    layer,
                    inputLabel: `[in${inputCounter}]`,
                    startTimeGlobal: shotStartSec + layer.startTime / fps,
                    endTimeGlobal: shotStartSec + (layer.startTime + layer.duration) / fps,
                });
                inputCounter++;
            }
        }

        return layers;
    }

    private buildComplexFiltergraph(
        layers: CompositorLayer[],
        settings: ExportSettings,
    ): { filterGraphStr: string; inputArgs: string[]; outputMapArgs: string[] } {
        this.currentInputArgs = [];
        this.currentInputIdx = 0;
        this.currentFilterParts = [];
        const audioInputs: string[] = [];
        let lastVideoLabel = 'base';

        const { width, height } = settings.resolution;
        this.currentFilterParts.push(
            `color=c=black:s=${width}x${height}:d=${this.getTimelineDuration(layers)}[${lastVideoLabel}]`,
        );

        for (const cl of layers) {
            const { layer } = cl;

            switch (layer.type) {
                case 'media': {
                    const mediaData = layer.data as MediaLayerData;
                    this.currentInputArgs.push('-i', mediaData.sourceUrl);
                    const srcLabel = `${this.currentInputIdx}:v`;

                    const processedLabel = `m${this.currentInputIdx}`;
                    this.currentInputIdx++;
                    
                    const perLayer = this.buildMediaLayerFilters(
                        srcLabel,
                        processedLabel,
                        mediaData,
                        layer,
                        settings.resolution,
                    );
                    this.currentFilterParts.push(...perLayer);

                    const nextLabel = `comp${this.currentInputIdx}`;
                    const enable = `enable='between(t,${cl.startTimeGlobal},${cl.endTimeGlobal})'`;
                    const transform = mediaData.transform;
                    const x = Math.round(transform.position.x);
                    const y = Math.round(transform.position.y);

                    this.currentFilterParts.push(
                        `[${lastVideoLabel}][${processedLabel}]overlay=x=${x}:y=${y}:${enable}[${nextLabel}]`,
                    );
                    lastVideoLabel = nextLabel;
                    break;
                }

                case 'text': {
                    const textData = layer.data as TextLayerData;
                    const nextLabel = `txt${this.currentInputIdx}`;
                    this.currentInputIdx++;

                    const drawtext = this.buildDrawtextFilter(textData, cl, settings.resolution);
                    const enable = `enable='between(t,${cl.startTimeGlobal},${cl.endTimeGlobal})'`;

                    this.currentFilterParts.push(
                        `[${lastVideoLabel}]${drawtext}:${enable}[${nextLabel}]`,
                    );
                    lastVideoLabel = nextLabel;
                    break;
                }

                case 'audio': {
                    const audioData = layer.data as AudioLayerData;
                    this.currentInputArgs.push('-i', audioData.sourceUrl);
                    const aidx = this.currentInputIdx;
                    this.currentInputIdx++;

                    let audioLabel = `a${aidx}`;
                    const audioFilters: string[] = [];

                    if (audioData.volume !== 1) {
                        audioFilters.push(`volume=${audioData.volume}`);
                    }
                    if (audioData.fadeIn > 0) {
                        audioFilters.push(`afade=t=in:d=${audioData.fadeIn / settings.fps}`);
                    }
                    if (audioData.fadeOut > 0) {
                        audioFilters.push(`afade=t=out:st=${cl.endTimeGlobal - audioData.fadeOut / settings.fps}:d=${audioData.fadeOut / settings.fps}`);
                    }

                    if (audioFilters.length > 0) {
                        this.currentFilterParts.push(`[${aidx}:a]${audioFilters.join(',')}[${audioLabel}]`);
                    } else {
                        audioLabel = `${aidx}:a`;
                    }
                    audioInputs.push(`[${audioLabel}]`);
                    break;
                }

                case 'transitions':
                    break;

                default:
                    break;
            }
        }

        let audioMapArg: string[] = [];
        if (audioInputs.length > 0) {
            if (audioInputs.length === 1) {
                audioMapArg = ['-map', audioInputs[0].replace(/[\[\]]/g, '')];
            } else {
                const mixLabel = 'amixed';
                this.currentFilterParts.push(
                    `${audioInputs.join('')}amix=inputs=${audioInputs.length}:duration=longest[${mixLabel}]`,
                );
                audioMapArg = ['-map', `[${mixLabel}]`];
            }
        }

        const filterGraphStr = this.currentFilterParts.join(';');
        const inputArgs = [...this.currentInputArgs];
        const outputMapArgs = ['-map', `[${lastVideoLabel}]`, ...audioMapArg];

        return { filterGraphStr, inputArgs, outputMapArgs };
    }

    private buildMediaLayerFilters(
        srcLabel: string,
        outLabel: string,
        mediaData: MediaLayerData,
        layer: Layer,
        resolution: Resolution,
    ): string[] {
        const filters: string[] = [];
        let currentLabel = srcLabel;
        let stepIdx = 0;

        const step = () => `${outLabel}_s${stepIdx++}`;

        if (mediaData.trim) {
            const nextL = step();
            filters.push(`[${currentLabel}]trim=start=${mediaData.trim.start}:end=${mediaData.trim.end},setpts=PTS-STARTPTS[${nextL}]`);
            currentLabel = nextL;
        }

        const sx = mediaData.transform.scale.x;
        const sy = mediaData.transform.scale.y;
        const rot = mediaData.transform.rotation;
        if (sx !== 1 || sy !== 1 || rot !== 0) {
            const nextL = step();
            const scaleW = Math.round(resolution.width * sx);
            const scaleH = Math.round(resolution.height * sy);
            let filterStr = `[${currentLabel}]scale=${scaleW}:${scaleH}`;
            if (rot !== 0) {
                const rotRad = (rot * Math.PI) / 180;
                filterStr += `,rotate=${rotRad}:c=none`;
            }
            filterStr += `[${nextL}]`;
            filters.push(filterStr);
            currentLabel = nextL;
        }

        if (mediaData.effects?.chromaKey) {
            const ck = mediaData.effects.chromaKey;
            const nextL = step();
            filters.push(`[${currentLabel}]chromakey=${ck.color}:${ck.similarity / 100}:0.1[${nextL}]`);
            currentLabel = nextL;
        }

        if (mediaData.effects?.colorCorrection) {
            const cc = mediaData.effects.colorCorrection;
            const nextL = step();
            filters.push(`[${currentLabel}]eq=brightness=${cc.brightness}:contrast=${cc.contrast}:saturation=${cc.saturation}[${nextL}]`);
            currentLabel = nextL;
        }

        if (mediaData.mask && mediaData.mask.type === 'image' && mediaData.mask.source) {
            this.currentInputArgs.push('-i', mediaData.mask.source);
            const maskLabel = `${this.currentInputIdx}:v`;
            this.currentInputIdx++;

            const nextL = step();
            filters.push(`[${currentLabel}][${maskLabel}]alphamerge[${nextL}]`);
            currentLabel = nextL;
        }

        if (layer.opacity < 1) {
            const nextL = step();
            filters.push(`[${currentLabel}]format=rgba,colorchannelmixer=aa=${layer.opacity}[${nextL}]`);
            currentLabel = nextL;
        }

        if (mediaData.effects?.blur && mediaData.effects.blur > 0) {
            const nextL = step();
            filters.push(`[${currentLabel}]boxblur=${mediaData.effects.blur}[${nextL}]`);
            currentLabel = nextL;
        }

        if (currentLabel !== outLabel) {
            filters.push(`[${currentLabel}]null[${outLabel}]`);
        }

        return filters;
    }

    private buildDrawtextFilter(
        textData: TextLayerData,
        cl: CompositorLayer,
        resolution: Resolution,
    ): string {
        const style: Partial<RichTextStyle> = textData.style ?? {};
        const fontSize = style.fontSize ?? textData.size ?? 24;
        const fillColor = style.fillColor ?? textData.color ?? '#FFFFFF';

        const escapedText = (textData.content ?? '')
            .replace(/'/g, "\\'")
            .replace(/:/g, '\\:')
            .replace(/\n/g, '\\n');

        const x = textData.position?.x
            ? Math.round(textData.position.x * resolution.width)
            : Math.round(resolution.width / 2);
        const y = textData.position?.y
            ? Math.round(textData.position.y * resolution.height)
            : Math.round(resolution.height / 2);

        const parts = [
            `drawtext=text='${escapedText}'`,
            `fontfile=''`,
            `fontsize=${fontSize}`,
            `fontcolor=${fillColor}`,
            `x=${x}`,
            `y=${y}`,
        ];

        if (style.strokeColor && style.strokeWidth) {
            parts.push(`borderw=${style.strokeWidth}`, `bordercolor=${style.strokeColor}`);
        }

        if (style.shadowColor && style.shadowBlur) {
            parts.push(`shadowcolor=${style.shadowColor}`, `shadowx=${style.shadowOffsetX ?? 2}`, `shadowy=${style.shadowOffsetY ?? 2}`);
        }

        return parts.join(':');
    }

    private async runFFmpeg(
        inputArgs: string[],
        filterGraphStr: string,
        outputMapArgs: string[],
        job: RenderJob,
    ): Promise<void> {
        const fullCmd = [
            'ffmpeg',
            ...inputArgs,
            '-filter_complex',
            `"${filterGraphStr}"`,
            ...outputMapArgs,
            '-c:v', job.settings.codec,
            '-preset', job.settings.preset ?? 'medium',
            '-crf', String(job.settings.quality ?? 23),
            '-y',
            job.outputPath,
        ];

        console.log('[FFmpegRenderService] Command:', fullCmd.join(' '));

        if (electronFFmpegBridge.isElectron) {
            const startTime = Date.now();
            const totalFrames = this.estimateTotalFrames(job);

            const unsubscribe = electronFFmpegBridge.onRenderProgress(job.id, (data) => {
                if (data.done) {
                    job.progress = 95;
                    job.currentStage = 'Finalizing...';
                } else {
                    const pct = 20 + Math.round((data.frame / totalFrames) * 75);
                    job.progress = Math.min(pct, 95);
                    job.currentStage = `Encoding frame ${data.frame}/${totalFrames}`;
                }

                this.emitProgress(job.id, {
                    jobId: job.id,
                    stage: 'encoding',
                    progress: job.progress,
                    message: job.currentStage,
                    fps: data.frame > 0 ? data.frame / ((Date.now() - startTime) / 1000) : 0,
                    timeElapsed: (Date.now() - startTime) / 1000,
                });
            });

            try {
                await electronFFmpegBridge.render(
                    job.id,
                    inputArgs,
                    filterGraphStr,
                    outputMapArgs,
                    job.settings,
                    job.outputPath,
                );
            } finally {
                unsubscribe();
            }
            return;
        }

        console.warn('[FFmpegRenderService] Not in Electron — using simulation mode');
        const layers = this.flattenTimeline(job.shots, job.settings.fps);
        const totalDuration = this.getTimelineDuration(layers);
        const simulatedFrames = Math.ceil(totalDuration * job.settings.fps);
        const startTime = Date.now();

        for (let frame = 0; frame <= simulatedFrames; frame += Math.ceil(simulatedFrames / 50)) {
            if (job.status === 'cancelled') throw new Error('Render cancelled by user');

            const pct = 20 + Math.round((frame / simulatedFrames) * 75);
            job.progress = pct;
            job.currentStage = `Encoding frame ${frame}/${simulatedFrames}`;

            this.emitProgress(job.id, {
                jobId: job.id,
                stage: 'encoding',
                progress: pct,
                message: job.currentStage,
                fps: 30,
                timeElapsed: (Date.now() - startTime) / 1000,
            });

            await this.sleep(50);
        }
    }

    private estimateTotalFrames(job: RenderJob): number {
        const layers = this.flattenTimeline(job.shots, job.settings.fps);
        const duration = this.getTimelineDuration(layers);
        return Math.ceil(duration * job.settings.fps);
    }

    private getTimelineDuration(layers: CompositorLayer[]): number {
        if (layers.length === 0) return 1;
        return Math.max(...layers.map(l => l.endTimeGlobal), 1);
    }

    private updateJob(job: RenderJob, status: RenderJob['status'], progress: number, stage: string): void {
        job.status = status;
        job.progress = progress;
        job.currentStage = stage;
    }

    private emitProgress(jobId: string, progress: RenderProgress): void {
        const listeners = this.progressListeners.get(jobId);
        if (listeners) listeners.forEach(fn => fn(progress));
    }

    private sleep(ms: number): Promise<void> {
        return new Promise(resolve => setTimeout(resolve, ms));
    }
}

export const ffmpegRenderService = new FFmpegRenderService();

/**
 * Grid Editor Configuration Export/Import Service
 * 
 * Handles exporting and importing grid editor configurations in multiple formats.
 * Supports JSON, YAML, and URL-encoded configurations for sharing.
 * 
 * Exigences: 15.1, 15.2, 15.3, 15.4, 15.5, 15.6, 15.7, 15.8
 */

import type { GridLayoutConfig, GridPanel } from '../../types/gridEditorAdvanced';

// ============================================================================
// Types
// ============================================================================

export interface GridEditorConfiguration {
  // Grid layout settings
  layout: GridLayoutConfig;
  
  // Visual preferences
  visualPreferences: {
    theme?: 'light' | 'dark';
    showGridLines: boolean;
    showAlignmentGuides: boolean;
    animationsEnabled: boolean;
  };
  
  // Snap settings
  snapSettings: {
    enabled: boolean;
    threshold: number;
    gridSizes: number[];
  };
  
  // Optional: Panel positions (for full state export)
  panels?: GridPanel[];
}

export interface GridEditorTemplate {
  // Template metadata
  name: string;
  description?: string;
  author?: string;
  tags?: string[];
  
  // Reusable configuration (no panel positions)
  layout: Omit<GridLayoutConfig, 'rows'>; // Rows are dynamic
  visualPreferences: GridEditorConfiguration['visualPreferences'];
  snapSettings: GridEditorConfiguration['snapSettings'];
}

export interface ExportMetadata {
  version: string;
  exportedAt: string;
  exportedBy?: string;
  type: 'full' | 'template';
  format: 'json' | 'yaml' | 'url';
}

export interface ExportedGridConfiguration {
  metadata: ExportMetadata;
  configuration: GridEditorConfiguration | GridEditorTemplate;
}

export interface ImportResult {
  success: boolean;
  configuration?: GridEditorConfiguration | GridEditorTemplate;
  errors?: string[];
  warnings?: string[];
  conflicts?: ConfigurationConflict[];
}

export interface ConfigurationConflict {
  field: string;
  currentValue: unknown;
  importedValue: unknown;
  suggestion: 'keep_current' | 'use_imported' | 'merge';
}

export type ExportFormat = 'json' | 'yaml' | 'url';

// ============================================================================
// Constants
// ============================================================================

const CURRENT_VERSION = '1.0.0';
const URL_PREFIX = 'storycore://grid-config/';

// ============================================================================
// Export Functions
// ============================================================================

/**
 * Export grid editor configuration
 * Exigences: 15.1, 15.3, 15.7
 */
export function exportGridConfiguration(
  configuration: GridEditorConfiguration,
  format: ExportFormat = 'json',
  filename?: string
): void {
  const exportData: ExportedGridConfiguration = {
    metadata: {
      version: CURRENT_VERSION,
      exportedAt: new Date().toISOString(),
      type: 'full',
      format
    },
    configuration
  };

  switch (format) {
    case 'json':
      exportAsJSON(exportData, filename);
      break;
    case 'yaml':
      exportAsYAML(exportData, filename);
      break;
    case 'url':
      exportAsURL(exportData);
      break;
  }
}

/**
 * Export as template (reusable configuration without panel positions)
 * Exigence: 15.6
 */
export function exportAsTemplate(
  configuration: GridEditorConfiguration,
  templateInfo: Pick<GridEditorTemplate, 'name' | 'description' | 'author' | 'tags'>,
  format: ExportFormat = 'json',
  filename?: string
): void {
  // Filter out non-reusable parameters
  const template: GridEditorTemplate = {
    ...templateInfo,
    layout: {
      columns: configuration.layout.columns,
      gap: configuration.layout.gap,
      cellSize: configuration.layout.cellSize,
      snapEnabled: configuration.layout.snapEnabled,
      snapThreshold: configuration.layout.snapThreshold,
      showGridLines: configuration.layout.showGridLines
    },
    visualPreferences: configuration.visualPreferences,
    snapSettings: configuration.snapSettings
  };

  const exportData: ExportedGridConfiguration = {
    metadata: {
      version: CURRENT_VERSION,
      exportedAt: new Date().toISOString(),
      type: 'template',
      format
    },
    configuration: template
  };

  switch (format) {
    case 'json':
      exportAsJSON(exportData, filename || `${templateInfo.name}-template.json`);
      break;
    case 'yaml':
      exportAsYAML(exportData, filename || `${templateInfo.name}-template.yaml`);
      break;
    case 'url':
      exportAsURL(exportData);
      break;
  }
}

/**
 * Export as JSON file
 */
function exportAsJSON(data: ExportedGridConfiguration, filename?: string): void {
  const json = JSON.stringify(data, null, 2);
  const blob = new Blob([json], { type: 'application/json' });
  downloadFile(blob, filename || `grid-config-${Date.now()}.json`);
}

/**
 * Export as YAML file
 */
function exportAsYAML(data: ExportedGridConfiguration, filename?: string): void {
  const yaml = convertToYAML(data);
  const blob = new Blob([yaml], { type: 'text/yaml' });
  downloadFile(blob, filename || `grid-config-${Date.now()}.yaml`);
}

/**
 * Export as shareable URL
 * Exigence: 15.4
 */
function exportAsURL(data: ExportedGridConfiguration): void {
  const json = JSON.stringify(data);
  const base64 = btoa(encodeURIComponent(json));
  const url = `${URL_PREFIX}${base64}`;
  
  // Copy to clipboard
  navigator.clipboard.writeText(url).then(() => {
    // Show notification to user
    showNotification('Configuration URL copied to clipboard!', 'success');
  }).catch(err => {
    console.error('Failed to copy URL:', err);
    showNotification('Failed to copy URL to clipboard', 'error');
  });
}

