/**
 * Helper to join paths safely in the renderer
 */
function pathJoin(base: string, part: string): string {
    if (!base) return part;
    // Normalize slashes to the system preferred style
    const normalizedBase = base.replace(/\/|\\/g, base.includes('\\') ? '\\' : '/');
    const separator = normalizedBase.includes('\\') ? '\\' : '/';
    return normalizedBase.endsWith(separator) ? normalizedBase + part : normalizedBase + separator + part;
}

/**
 * Progress Tracking Service
 * 
 * Monitors generation task progress and provides real-time status updates.
 * Supports polling-based updates with configurable intervals.
 */

import type { GenerationTask } from '../types';

export interface ProgressUpdate {
  taskId: string;
  status: GenerationTask['status'];
  progress: number; // 0-100
  message?: string;
  error?: string;
  startedAt?: Date;
  completedAt?: Date;
}

export interface ProgressTrackingOptions {
  pollInterval?: number; // milliseconds, default 2000
  onProgress?: (update: ProgressUpdate) => void;
  onComplete?: (taskId: string) => void;
  onError?: (taskId: string, error: string) => void;
}

export interface ProgressTracker {
  update: (progress: number, message?: string) => void;
  complete: () => void;
}

export class ProgressTrackingService {
  private pollingIntervals: Map<string, ReturnType<typeof setInterval>> = new Map();
  private baseUrl: string;
  private trackers: Map<string, ProgressTracker> = new Map();

  constructor(baseUrl: string = import.meta.env.VITE_BACKEND_URL || 'http://localhost:3000') {
    this.baseUrl = baseUrl;
  }

  /**
   * Start tracking a task's progress
   */
  startTracking(taskId: string, options: ProgressTrackingOptions = {}): void {
    // Stop any existing tracking for this task
    this.stopTracking(taskId);

    const pollInterval = options.pollInterval || 2000;

    // Start polling
    const intervalId = setInterval(async () => {
      try {
        const update = await this.fetchProgress(taskId);
        
        // Notify progress callback
        if (options.onProgress) {
          options.onProgress(update);
        }

        // Check if task is complete
        if (update.status === 'completed') {
          this.stopTracking(taskId);
          if (options.onComplete) {
            options.onComplete(taskId);
          }
        } else if (update.status === 'failed') {
          this.stopTracking(taskId);
          if (options.onError) {
            options.onError(taskId, update.error || 'Task failed');
          }
        }
      } catch (error) {
        console.error(`Error tracking task ${taskId}:`, error);
        if (options.onError) {
          options.onError(taskId, error instanceof Error ? error.message : 'Unknown error');
        }
      }
    }, pollInterval);

    this.pollingIntervals.set(taskId, intervalId);
  }

  /**
   * Stop tracking a task's progress
   */
  stopTracking(taskId: string): void {
    const intervalId = this.pollingIntervals.get(taskId);
    if (intervalId) {
      clearInterval(intervalId);
      this.pollingIntervals.delete(taskId);
    }
  }

  /**
   * Stop tracking all tasks
   */
  stopAllTracking(): void {
    this.pollingIntervals.forEach((intervalId) => clearInterval(intervalId));
    this.pollingIntervals.clear();
  }

  /**
   * Create a progress tracker for local progress tracking
   */
  createTracker(taskId: string, options: { total: number; description?: string }): ProgressTracker {
    // Stop any existing tracker for this task
    if (this.trackers.has(taskId)) {
      this.trackers.delete(taskId);
    }

    let _currentProgress = 0;
    const tracker: ProgressTracker = {
      update: (progress: number, _message?: string) => {
        currentProgress = progress;
      },
      complete: () => {
        currentProgress = options.total;
        this.trackers.delete(taskId);
      }
    };

    this.trackers.set(taskId, tracker);
    
    return tracker;
  }

  /**
   * Fetch current progress for a task
   */
  async fetchProgress(taskId: string): Promise<ProgressUpdate> {
    const response = await fetch(`${this.baseUrl}/api/tasks/${taskId}/progress`);
    
    if (!response.ok) {
      throw new Error(`Failed to fetch progress: ${response.statusText}`);
    }

    const data = await response.json();
    
    return {
      taskId: data.taskId,
      status: data.status,
      progress: data.progress || 0,
      message: data.message,
      error: data.error,
      startedAt: data.startedAt ? new Date(data.startedAt) : undefined,
      completedAt: data.completedAt ? new Date(data.completedAt) : undefined,
    };
  }

  /**
   * Fetch progress for multiple tasks
   */
  async fetchMultipleProgress(taskIds: string[]): Promise<ProgressUpdate[]> {
    const promises = taskIds.map((taskId) => this.fetchProgress(taskId));
    return Promise.all(promises);
  }

  /**
   * Check if a task is being tracked
   */
  isTracking(taskId: string): boolean {
    return this.pollingIntervals.has(taskId);
  }

  /**
   * Get all tracked task IDs
   */
  getTrackedTaskIds(): string[] {
    return Array.from(this.pollingIntervals.keys());
  }
}

/**
 * Mock Progress Tracking Service for development/testing
 */
export class MockProgressTrackingService extends ProgressTrackingService {
  private mockProgress: Map<string, ProgressUpdate> = new Map();
  private mockDelay: number = 1000;
  private mockTrackers: Map<string, ProgressTracker> = new Map();

  setMockProgress(taskId: string, update: ProgressUpdate): void {
    this.mockProgress.set(taskId, update);
  }

  setMockDelay(delay: number): void {
    this.mockDelay = delay;
  }

  createTracker(taskId: string, options: { total: number; description?: string }): ProgressTracker {
    let _currentProgress = 0;
    const tracker: ProgressTracker = {
      update: (progress: number, _message?: string) => {
        currentProgress = progress;
      },
      complete: () => {
        currentProgress = options.total;
        this.mockTrackers.delete(taskId);
      }
    };

    this.mockTrackers.set(taskId, tracker);
    
    return tracker;
  }

  async fetchProgress(taskId: string): Promise<ProgressUpdate> {
    // Simulate network delay
    await new Promise((resolve) => setTimeout(resolve, this.mockDelay));

    // Return mock progress or simulate progress
    if (this.mockProgress.has(taskId)) {
      return this.mockProgress.get(taskId)!;
    }

    // Simulate progressive completion
    const existingProgress = this.mockProgress.get(taskId);
    const currentProgress = existingProgress?.progress || 0;
    
    if (currentProgress >= 100) {
      return {
        taskId,
        status: 'completed',
        progress: 100,
        message: 'Task completed successfully',
        completedAt: new Date(),
      };
    }

    const newProgress = Math.min(currentProgress + 10, 100);
    const update: ProgressUpdate = {
      taskId,
      status: newProgress >= 100 ? 'completed' : 'processing',
      progress: newProgress,
      message: `Processing... ${newProgress}%`,
      startedAt: existingProgress?.startedAt || new Date(),
      completedAt: newProgress >= 100 ? new Date() : undefined,
    };

    this.mockProgress.set(taskId, update);
    return update;
  }
}

/**
 * Factory function to create the appropriate service
 */
export function createProgressTrackingService(useMock: boolean = false): ProgressTrackingService {
  if (useMock || import.meta.env.VITE_USE_MOCK_BACKEND === 'true') {
    return new MockProgressTrackingService();
  }
  return new ProgressTrackingService();
}

/**
 * ReferenceInheritanceService - Propagates references between levels
 * 
 * Manages reference inheritance across three levels:
 * - Master → Sequence: Character/location/style references
 * - Sequence → Shot: All sequence references
 * 
 * Features:
 * - Automatic inheritance on creation
 * - Reference resolution with precedence rules
 * - Override management for shot-level modifications
 * - Change propagation across the inheritance chain
 */
import { LegacyAny } from '@/types/legacy';


import type {
  MasterReferenceSheet,
  CharacterAppearanceSheet,
  LocationAppearanceSheet,
  GlobalStyleSheet,
  SequenceReferenceSheet,
  ShotReference,
  ConsistencyOverride,
  SequenceStyle,
  ReferenceImage,
} from '../types/reference';
import { v4 as uuidv4 } from 'uuid';
import { getPerformanceMonitoringService } from './performanceMonitoringService';
import { referenceMetadataCache, estimateSize } from '../utils/memoryMonitor';
import type { ReferenceSheetService } from './referenceSheetService';

// ============================================================================
// Storage Path Helpers
// ============================================================================

/**
 * Cross-platform path joining utility
 */
function joinPath(...parts: string[]): string {
  return parts.join('/').replace(/\/+/g, '/');
}

/**
 * Get the path to the references directory for a project
 */
function getReferencesDir(projectPath: string): string {
  return joinPath(projectPath, 'references');
}

/**
 * Get the path to a sequence reference sheet file
 */
function getSequenceSheetPath(projectPath: string, sequenceId: string): string {
  return joinPath(getReferencesDir(projectPath), `sequence_${sequenceId}.json`);
}

/**
 * Get the path to a shot reference file
 */
function getShotReferencePath(projectPath: string, shotId: string): string {
  return joinPath(getReferencesDir(projectPath), `shot_${shotId}.json`);
}

