    this.backendApi = backendApi || new BackendApiService();
    this.errorHandler = errorHandler || new GenerationErrorHandler();
  }

  /**
   * Generate sequence through complete pipeline
   * Requirements: 3.2, 3.3, 3.4, 3.5
   * 
   * @param project - Project with shots and prompts
   * @param options - Generation options with callbacks
   * @returns Generation results or null if cancelled/failed
   */
  async generateSequence(
    project: Project,
    options: GenerationOptions = {}
  ): Promise<GenerationResults | null> {
    const {
      onProgress,
      onStageComplete,
      onError,
      retryAttempts = 3,
      retryDelayMs = 2000,
    } = options;

    // Initialize abort controller for cancellation
    this.abortController = new AbortController();
    this.startTime = Date.now();

    try {
      // Validate project has shots with valid prompts
      if (!project.shots || project.shots.length === 0) {
        throw new Error('Project has no shots to generate');
      }

      const totalShots = project.shots.length;
      let currentShot = 0;

      // Reset error handler for new generation
      this.errorHandler.reset();

      // Stage 1: Generate Master Coherence Sheet (3x3 grid)
      this.currentStage = 'grid';
      onProgress?.({
        stage: 'grid',
        progress: 0,
        currentShot: 0,
        totalShots,
        startTime: this.startTime,
      });

      const gridResult = await this.executeWithRetry(
        () => this.generateMasterCoherenceSheet(project),
        retryAttempts,
        retryDelayMs,
        'grid',
        onError
      );

      if (!gridResult) {
        return null; // Cancelled or failed
      }

      // Save partial results after grid generation
      this.errorHandler.savePartialResults(
        project.id,
        ['grid'],
        [],
        gridResult.masterCoherenceSheetUrl
      );

      onStageComplete?.('grid', gridResult);
      onProgress?.({
        stage: 'grid',
        progress: 20,
        currentShot: 0,
        totalShots,
        startTime: this.startTime,
        estimatedCompletion: this.estimateCompletion(20, totalShots),
      });

      // Stage 2: Trigger ComfyUI integration
      this.currentStage = 'comfyui';
      onProgress?.({
        stage: 'comfyui',
        progress: 20,
        currentShot: 0,
        totalShots,
        startTime: this.startTime,
        estimatedCompletion: this.estimateCompletion(20, totalShots),
      });

      const comfyuiResult = await this.executeWithRetry(
        () => this.generateWithComfyUI(project, gridResult, (shotIndex) => {
          currentShot = shotIndex + 1;
          const progress = 20 + Math.floor((shotIndex / totalShots) * 40);
          onProgress?.({
            stage: 'comfyui',
            progress,
            currentShot,
            totalShots,
            startTime: this.startTime,
            estimatedCompletion: this.estimateCompletion(progress, totalShots),
          });
        }),
        retryAttempts,
        retryDelayMs,
        'comfyui',
        onError
      );

      if (!comfyuiResult) {
        return null;
      }

      // Save partial results after ComfyUI generation
      this.errorHandler.savePartialResults(
        project.id,
        ['grid', 'comfyui'],
        comfyuiResult.outputs.map(output => ({
          shotId: output.shotId,
          imageUrl: output.imageUrl,
          qaScore: 0,
          processingTime: 0,
        })),
        gridResult.masterCoherenceSheetUrl
      );

      onStageComplete?.('comfyui', comfyuiResult);
      onProgress?.({
        stage: 'comfyui',
        progress: 60,
        currentShot: totalShots,
        totalShots,
        startTime: this.startTime,
        estimatedCompletion: this.estimateCompletion(60, totalShots),
      });

      // Stage 3: Process through StoryCore pipeline (promotion, QA, autofix)
      this.currentStage = 'promotion';
      onProgress?.({
        stage: 'promotion',
        progress: 60,
        currentShot: 0,
        totalShots,
        startTime: this.startTime,
        estimatedCompletion: this.estimateCompletion(60, totalShots),
      });

      const promotionResult = await this.executeWithRetry(
        () => this.promoteShots(comfyuiResult, (shotIndex) => {
          const progress = 60 + Math.floor((shotIndex / totalShots) * 15);
          onProgress?.({
            stage: 'promotion',
            progress,
            currentShot: shotIndex + 1,
            totalShots,
            startTime: this.startTime,
            estimatedCompletion: this.estimateCompletion(progress, totalShots),
          });
        }),
        retryAttempts,
        retryDelayMs,
        'promotion',
        onError
      );

      if (!promotionResult) {
        return null;
      }

      // Save partial results after promotion
      this.errorHandler.savePartialResults(
        project.id,
        ['grid', 'comfyui', 'promotion'],
        promotionResult.promotedShots.map(shot => ({
          shotId: shot.shotId,
          imageUrl: shot.imageUrl,
          qaScore: 0,
          processingTime: shot.processingTime,
        })),
        gridResult.masterCoherenceSheetUrl
      );

      onStageComplete?.('promotion', promotionResult);

      // QA Stage
      this.currentStage = 'qa';
      onProgress?.({
        stage: 'qa',
        progress: 75,
        currentShot: 0,
        totalShots,
        startTime: this.startTime,
        estimatedCompletion: this.estimateCompletion(75, totalShots),
      });

      const qaResult = await this.executeWithRetry(
        () => this.runQAAnalysis(promotionResult),
        retryAttempts,
        retryDelayMs,
        'qa',
        onError
      );

      if (!qaResult) {
        return null;
      }

      onStageComplete?.('qa', qaResult);
      onProgress?.({
        stage: 'qa',
        progress: 90,
        currentShot: totalShots,
        totalShots,
        startTime: this.startTime,
        estimatedCompletion: this.estimateCompletion(90, totalShots),
      });

      // Stage 4: Export results
      this.currentStage = 'export';
      onProgress?.({
        stage: 'export',
        progress: 90,
        currentShot: totalShots,
        totalShots,
        startTime: this.startTime,
        estimatedCompletion: this.estimateCompletion(90, totalShots),
      });

      const exportResult = await this.executeWithRetry(
        () => this.exportResults(project, gridResult, promotionResult, qaResult),
        retryAttempts,
        retryDelayMs,
        'export',
        onError
      );

      if (!exportResult) {
        return null;
      }

      onStageComplete?.('export', exportResult);
      onProgress?.({
        stage: 'complete',
        progress: 100,
        currentShot: totalShots,
        totalShots,
        startTime: this.startTime,
      });

      // Compile final results
      const generatedShots: GeneratedShot[] = promotionResult.promotedShots.map(shot => ({
        shotId: shot.shotId,
        imageUrl: shot.imageUrl,
        qaScore: qaResult.report.shotScores.find(s => s.shotId === shot.shotId)?.score || 0,
        processingTime: shot.processingTime,
      }));

      const results: GenerationResults = {
        success: true,
        masterCoherenceSheetUrl: gridResult.masterCoherenceSheetUrl,
        generatedShots,
        qaReport: qaResult.report,
        exportPackageUrl: exportResult.exportPackageUrl,
      };

      // Clear partial results after successful completion
      this.errorHandler.clearPartialResults(project.id);

      return results;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      
      // Save partial results on failure
      if (this.currentStage) {
        const generationError = createGenerationError(
          this.currentStage,
          errorMessage,
          undefined,
          true
        );

        this.errorHandler.savePartialResults(
          project.id,
          [],
          [],
          undefined,
          generationError
        );
      }

      onProgress?.({
        stage: 'error',
        progress: 0,
        error: errorMessage,
        startTime: this.startTime,
      });

      onError?.({
        stage: this.currentStage || 'grid',
        message: getUserFriendlyErrorMessage(error as Error),
        retryable: true,
      });

      return null;
    } finally {
      this.abortController = null;
      this.currentStage = null;
    }
  }

  /**
   * Cancel ongoing generation
   * Requirements: 8.5
   */
  cancel(): void {
    if (this.abortController) {
      this.abortController.abort();
      this.abortController = null;
    }
  }

  /**
   * Check if generation is in progress
   */
  isGenerating(): boolean {
    return this.abortController !== null;
  }

  // ============================================================================
  // Pipeline Stage Implementations
  // ============================================================================

  /**
   * Stage 1: Generate Master Coherence Sheet (3x3 grid)
   * Requirements: 3.3
   */
  private async generateMasterCoherenceSheet(
    project: Project
  ): Promise<GridGenerationResult> {
    this.checkAborted();

    // Call backend to generate grid
    const response = await this.backendApi.invokeCliCommand('grid', {
      project: project.name,
    });

    if (!response.success) {
      throw new Error(response.error || 'Failed to generate Master Coherence Sheet');
    }

    // Extract grid result from response
    const gridUrl = response.data?.gridUrl || `/projects/${project.name}/grid.png`;
    const gridImages = response.data?.gridImages || [];

    return {
      masterCoherenceSheetUrl: gridUrl,
      gridImages,
      generatedAt: Date.now(),
    };
  }

  /**
   * Stage 2: Generate shots with ComfyUI
   * Requirements: 3.4
   */
  private async generateWithComfyUI(
    project: Project,
    gridResult: GridGenerationResult,
    onShotProgress: (shotIndex: number) => void
  ): Promise<ComfyUIResult> {
    this.checkAborted();

    const outputs: Array<{ shotId: string; imageUrl: string }> = [];

    // Process each shot through ComfyUI
    for (let i = 0; i < project.shots.length; i++) {
      this.checkAborted();

      const shot = project.shots[i];
      onShotProgress(i);

      // Submit ComfyUI workflow for this shot
      const workflowResponse = await this.backendApi.submitComfyUIWorkflow({
        workflowId: 'image-generation',
        inputs: {
          prompt: shot.prompt,
          width: 512,
          height: 512,
          seed: -1,
          masterCoherenceSheet: gridResult.masterCoherenceSheetUrl,
        },
      });

      if (!workflowResponse.success || !workflowResponse.data) {
        throw new Error(`Failed to generate shot ${shot.id}: ${workflowResponse.error}`);
      }

      // Poll for completion
      const result = await this.pollComfyUICompletion(workflowResponse.data.promptId);
      
      if (result.outputs && result.outputs.length > 0) {
        outputs.push({
          shotId: shot.id,
          imageUrl: result.outputs[0].url,
        });
      }
    }

    return {
      promptId: `batch-${Date.now()}`,
      outputs,
    };
  }

  /**
   * Poll ComfyUI for workflow completion
   */
  private async pollComfyUICompletion(promptId: string): Promise<LegacyAny> {
    const maxAttempts = 60; // 5 minutes with 5 second intervals
    const pollInterval = 5000;

    for (let attempt = 0; attempt < maxAttempts; attempt++) {
      this.checkAborted();

      const statusResponse = await this.backendApi.getComfyUIStatus(promptId);
      
      if (!statusResponse.success || !statusResponse.data) {
        throw new Error('Failed to get ComfyUI status');
      }

      const status = statusResponse.data;

      if (status.status === 'completed') {
        return status;
      }

      if (status.status === 'failed') {
        throw new Error(status.error || 'ComfyUI workflow failed');
      }

      // Wait before next poll
      await this.delay(pollInterval);
    }

    throw new Error('ComfyUI workflow timeout');
  }

  /**
   * Stage 3a: Promote shots through StoryCore pipeline
   * Requirements: 3.5
   */
  private async promoteShots(
    comfyuiResult: ComfyUIResult,
    onShotProgress: (shotIndex: number) => void
  ): Promise<PromotionResult> {
    this.checkAborted();

    const promotedShots: Array<{
      shotId: string;
      imageUrl: string;
      processingTime: number;
    }> = [];

    for (let i = 0; i < comfyuiResult.outputs.length; i++) {
      this.checkAborted();

      const output = comfyuiResult.outputs[i];
      onShotProgress(i);

      const startTime = Date.now();

      // Call promotion engine
      const response = await this.backendApi.invokeCliCommand('promote', {
        shotId: output.shotId,
        imageUrl: output.imageUrl,
      });

      if (!response.success) {
        throw new Error(`Failed to promote shot ${output.shotId}: ${response.error}`);
      }

      const processingTime = Date.now() - startTime;

      promotedShots.push({
        shotId: output.shotId,
        imageUrl: response.data?.promotedUrl || output.imageUrl,
        processingTime,
      });
    }

    return { promotedShots };
  }

  /**
   * Stage 3b: Run QA analysis and autofix
   * Requirements: 3.5
   */
  private async runQAAnalysis(promotionResult: PromotionResult): Promise<QAResult> {
    this.checkAborted();

    // Call QA engine
    const response = await this.backendApi.invokeCliCommand('qa', {
      shots: promotionResult.promotedShots,
    });

    if (!response.success) {
      throw new Error(`QA analysis failed: ${response.error}`);
    }

    const qaData = response.data || {};

    const report: QAReport = {
      overallScore: qaData.overallScore || 0,
      shotScores: qaData.shotScores || [],
      autofixApplied: qaData.autofixApplied || false,
    };

    return {
      report,
      autofixApplied: report.autofixApplied,
    };
  }

  /**
   * Stage 4: Export results
   * Requirements: 3.5
   */
  private async exportResults(
    project: Project,
    gridResult: GridGenerationResult,
    promotionResult: PromotionResult,
    qaResult: QAResult
  ): Promise<ExportResult> {
    this.checkAborted();

    // Call export engine
    const response = await this.backendApi.invokeCliCommand('export', {
      project: project.name,
      gridUrl: gridResult.masterCoherenceSheetUrl,
      shots: promotionResult.promotedShots,
      qaReport: qaResult.report,
    });

    if (!response.success) {
      throw new Error(`Export failed: ${response.error}`);
    }

    return {
      exportPackageUrl: response.data?.exportUrl || `/exports/${project.name}-${Date.now()}.zip`,
      timestamp: Date.now(),
    };
  }

  // ============================================================================
  // Utility Methods
  // ============================================================================

  /**
   * Execute function with retry logic and exponential backoff
   * Requirements: 3.7, 9.5
   */
  private async executeWithRetry<T>(
    fn: () => Promise<T>,
    maxAttempts: number,
    delayMs: number,
    stage: PipelineStage,
    onError?: ErrorCallback
  ): Promise<T | null> {
    let attemptNumber = 1;

    while (attemptNumber <= maxAttempts) {
      try {
        this.checkAborted();
        return await fn();
      } catch (error) {
        const err = error instanceof Error ? error : new Error('Unknown error');

        // Don't retry if aborted
        if (this.abortController?.signal.aborted) {
          return null;
        }

        // Handle error with error handler
        const errorContext = {
          stage,
          timestamp: Date.now(),
          attemptNumber,
        };

        const handlerResult = this.errorHandler.handleError(err, errorContext);

        // Log error for debugging
        logError(err, errorContext);

        // Create generation error for callback
        const generationError = createGenerationError(
          stage,
          getUserFriendlyErrorMessage(err),
          undefined,
          handlerResult.canRetry
        );

        // Report error to callback
        onError?.(generationError);

        // Check if we should retry
        if (handlerResult.action === 'retry' && attemptNumber < maxAttempts) {
          // Wait before retry with exponential backoff
          const backoffDelay = handlerResult.suggestedDelay || delayMs * Math.pow(2, attemptNumber - 1);
          await this.delay(backoffDelay);
          attemptNumber++;
        } else {
          // No more retries, throw error
          throw err;
        }
      }
    }

    // Should not reach here, but throw error if we do
    throw new Error(`Stage ${stage} failed after ${maxAttempts} attempts`);
  }

  /**
   * Check if generation was aborted
   */
  private checkAborted(): void {
    if (this.abortController?.signal.aborted) {
      throw new Error('Generation cancelled');
    }
  }

  /**
   * Delay helper
   */
  private delay(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  /**
   * Estimate completion time based on current progress
   * Requirements: 8.3, 8.4
   */
  private estimateCompletion(currentProgress: number, totalShots: number): number {
    if (currentProgress === 0) {
      return 0;
    }

    const elapsed = Date.now() - this.startTime;
    const estimatedTotal = (elapsed / currentProgress) * 100;
    const remaining = estimatedTotal - elapsed;

    return Date.now() + remaining;
  }

  /**
   * Update backend API service
   */
  updateBackendApi(backendApi: BackendApiService): void {
    this.backendApi = backendApi;
  }

  /**
   * Get partial results for recovery
   * Requirements: 9.5
   */
  getPartialResults(projectId: string) {
    return this.errorHandler.loadPartialResults(projectId);
  }

  /**
   * Get error handler for advanced error management
   */
  getErrorHandler(): GenerationErrorHandler {
    return this.errorHandler;
  }
}

/**
 * Default sequence generation service instance
 */
export const sequenceGenerationService = new SequenceGenerationService();

/**
 * Anime Effect Renderer Service
 * 
 * Renders anime-style visual effects including speed lines, impact frames,
 * motion trails, and emotion effects using Canvas 2D API.
 */
import { LegacyAny } from '@/types/legacy';


import {
  AnimeEffect,
  SpeedLinesEffect,
  ImpactFrameEffect,
  MotionTrailEffect,
  EmotionEffect,
  MangaPanelEffect,
  AuraEffect
} from '@/types/animeEffect';

import { Point2D } from '@/types/sprite';

// ============================================================================
// Types
// ============================================================================

export interface RenderContext {
  ctx: CanvasRenderingContext2D;
  width: number;
  height: number;
  time: number;
  deltaTime: number;
}

export interface EffectRenderResult {
  success: boolean;
  error?: string;
}

// ============================================================================
// Anime Effect Renderer Class
// ============================================================================

export class AnimeEffectRenderer {
  private trailHistory: Map<string, ImageData[]> = new Map();
  private particleSystems: Map<string, Particle[]> = new Map();
  
  // ==========================================================================
  // Main Render Method
  // ==========================================================================

  /**
   * Render an effect to the canvas
   */
  render(
    context: RenderContext,
    effect: AnimeEffect,
    position: Point2D
  ): EffectRenderResult {
    if (!effect.enabled) {
      return { success: true };
    }

    try {
      switch (effect.type) {
        case 'speed_lines':
          return this.renderSpeedLines(context, effect, position);
        case 'impact_frame':
          return this.renderImpactFrame(context, effect, position);
        case 'motion_trail':
          return this.renderMotionTrail(context, effect, position);
        case 'emotion':
          return this.renderEmotion(context, effect, position);
        case 'manga_panel':
          return this.renderMangaPanel(context, effect, position);
        case 'aura':
          return this.renderAura(context, effect, position);
        default:
          return { success: false, error: `Unknown effect type: ${(effect as LegacyAny).type}` };
      }
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown render error'
      };
    }
  }

  // ==========================================================================
  // Speed Lines Renderer
  // ==========================================================================

  private renderSpeedLines(
    context: RenderContext,
    effect: SpeedLinesEffect,
    position: Point2D
  ): EffectRenderResult {
    const { ctx, width, height, time } = context;
    const {
      lineCount,
      lineLength,
      lineThickness,
      thicknessVariation,
      lineColor,
      lineOpacity,
      useGradient,
      gradientEndColor,
      direction,
      angle,
      _focalPoint,
      spiralTightness,
      style,
      lineCap,
      taperLines,
      glowEffect,
      glowColor,
      glowBlur,
      animated,
      animationSpeed,
      intensity
    } = effect;

    ctx.save();
    
    // Apply intensity
    ctx.globalAlpha = lineOpacity * intensity;

    // Setup glow if enabled
    if (glowEffect && glowColor) {
      ctx.shadowColor = glowColor;
      ctx.shadowBlur = glowBlur || 5;
    }

    // Calculate animation offset
    const animOffset = animated ? (time * animationSpeed * 0.001) % 1 : 0;

    // Generate lines based on direction type
    for (let i = 0; i < lineCount; i++) {
      const lineProgress = (i / lineCount + animOffset) % 1;
      
      let startX: number, startY: number, endX: number, endY: number;
      
      switch (direction) {
        case 'linear':
          // Linear lines in a direction
          const linearAngle = (angle * Math.PI) / 180;
          const spreadY = (height * 0.8) * (i / lineCount - 0.5);
          startX = -lineLength * 0.5;
          startY = position.y + spreadY;
          endX = startX + lineLength;
          endY = startY;
          
          // Rotate around center
          const cos = Math.cos(linearAngle);
          const sin = Math.sin(linearAngle);
          const cx = position.x;
          const cy = position.y;
          const rx1 = cos * (startX - cx) - sin * (startY - cy) + cx;
          const ry1 = sin * (startX - cx) + cos * (startY - cy) + cy;
          const rx2 = cos * (endX - cx) - sin * (endY - cy) + cx;
          const ry2 = sin * (endX - cx) + cos * (endY - cy) + cy;
          startX = rx1; startY = ry1;
          endX = rx2; endY = ry2;
          break;

        case 'radial':
          // Radial lines from focal point
          const radialAngle = (2 * Math.PI * i) / lineCount;
          const fx = position.x + (focalPoint.x - 0.5) * width;
          const fy = position.y + (focalPoint.y - 0.5) * height;
          startX = fx;
          startY = fy;
          endX = fx + Math.cos(radialAngle) * lineLength * lineProgress;
          endY = fy + Math.sin(radialAngle) * lineLength * lineProgress;
          break;

        case 'spiral':
          // Spiral lines
          const spiralAngle = (2 * Math.PI * i) / lineCount + animOffset * 2 * Math.PI;
          const spiralRadius = lineLength * lineProgress * spiralTightness;
          startX = position.x;
          startY = position.y;
          endX = startX + Math.cos(spiralAngle) * spiralRadius;
          endY = startY + Math.sin(spiralAngle) * spiralRadius;
          break;

        default:
          startX = position.x;
          startY = position.y - lineLength / 2;
          endX = position.x;
          endY = position.y + lineLength / 2;
      }

      // Calculate thickness with variation
      const thickness = lineThickness * (1 + (Math.random() - 0.5) * thicknessVariation * 2);

      // Draw the line
      ctx.beginPath();
      ctx.lineCap = lineCap;
      ctx.lineWidth = taperLines ? thickness * (1 - lineProgress * 0.5) : thickness;

      // Apply gradient if enabled
      if (useGradient && gradientEndColor) {
        const gradient = ctx.createLinearGradient(startX, startY, endX, endY);
        gradient.addColorStop(0, lineColor);
        gradient.addColorStop(1, gradientEndColor);
        ctx.strokeStyle = gradient;
      } else {
        ctx.strokeStyle = lineColor;
      }

      ctx.moveTo(startX, startY);
      ctx.lineTo(endX, endY);
      ctx.stroke();
    }

    ctx.restore();
    return { success: true };
  }

  // ==========================================================================
  // Impact Frame Renderer
  // ==========================================================================

  private renderImpactFrame(
    context: RenderContext,
    effect: ImpactFrameEffect,
    position: Point2D
  ): EffectRenderResult {
    co_nst { ctx, width, height, time } = context;
    const {
      impactType,
      impactSize,
      impactShape,
      flashColor,
      _flashDuration,
      flashIntensity,
      glowRadius,
      screenShake,
      particles,
      radiatingLines,
      radiatingLineCount,
      radiatingLineColor,
      intensity
    } = effect;

    const progress = Math.min(1, time / (effect.duration || 200));
    const flashProgress = Math.min(1, time / flashDuration);

    ctx.save();

    // Apply screen shake
    if (screenShake.enabled && progress < 0.5) {
      const shakeAmount = screenShake.intensity * 20 * (1 - progress * 2);
      ctx.translate(
        (Math.random() - 0.5) * shakeAmount,
        (Math.random() - 0.5) * shakeAmount
      );
    }

    // Draw flash
    if (flashProgress < 1) {
      const flashAlpha = flashIntensity * (1 - flashProgress) * intensity;
      ctx.fillStyle = flashColor;
      ctx.globalAlpha = flashAlpha;
      ctx.fillRect(0, 0, width, height);
    }

    // Draw impact shape
    ctx.globalAlpha = intensity * (1 - progress * 0.5);
    const centerX = position.x;
    const centerY = position.y;
    const size = impactSize * 50 * (1 + progress * 0.5);

    // Draw radiating lines
    if (radiatingLines) {
      ctx.strokeStyle = radiatingLineColor;
      ctx.lineWidth = 2;
      
      for (let i = 0; i < radiatingLineCount; i++) {
        const angle = (2 * Math.PI * i) / radiatingLineCount;
        const lineLength = size * (1.5 + progress);
        
        ctx.beginPath();
        ctx.moveTo(centerX, centerY);
        ctx.lineTo(
          centerX + Math.cos(angle) * lineLength,
          centerY + Math.sin(angle) * lineLength
        );
        ctx.stroke();
      }
    }

    // Draw impact shape
    switch (impactShape) {
      case 'circle':
        ctx.beginPath();
        ctx.arc(centerX, centerY, size, 0, Math.PI * 2);
        ctx.fillStyle = flashColor;
        ctx.globalAlpha = intensity * (1 - progress);
        ctx.fill();
        break;

      case 'star':
        this.drawStar(ctx, centerX, centerY, 5, size, size * 0.5, flashColor, intensity * (1 - progress));
        break;

      case 'burst':
        this.drawBurst(ctx, centerX, centerY, size, 12, flashColor, intensity * (1 - progress));
        break;

      case 'diamond':
        ctx.beginPath();
        ctx.moveTo(centerX, centerY - size);
        ctx.lineTo(centerX + size, centerY);
        ctx.lineTo(centerX, centerY + size);
        ctx.lineTo(centerX - size, centerY);
        ctx.closePath();
        ctx.fillStyle = flashColor;
        ctx.globalAlpha = intensity * (1 - progress);
        ctx.fill();
        break;
    }

    // Draw particles
    if (particles.enabled && progress < 0.8) {
      this.drawParticles(ctx, effect, centerX, centerY, time, progress);
    }

    ctx.restore();
    return { success: true };
  }

  // ==========================================================================
  // Motion Trail Renderer
  // ==========================================================================

  private renderMotionTrail(
    context: RenderContext,
    effect: MotionTrailEffect,
    position: Poi_nt2D
  ): EffectRenderResult {
    const { ctx, time } = context;
    const {
      trailLength,
      _trailOpacity,
      trailColor,
      trailBlur,
      _fadeMode,
      _persistence,
      _style,
      _outlineThickness,
      outlineColor,
      colorShift,
      intensity
    } = effect;

    // This is a simplified implementation
    // A full implementation would capture sprite frames
    
    ctx.save();
    ctx.globalAlpha = trailOpacity * intensity;

    // Draw trail segments
    for (let i = 0; i < trailLength; i++) {
      const segmentProgress = i / trailLength;
      let alpha: number;
      
      switch (fadeMode) {
        case 'linear':
          alpha = 1 - segmentProgress;
          break;
        case 'ease':
          alpha = 1 - Math.pow(segmentProgress, 2);
          break;
        case 'exponential':
          alpha = Math.pow(1 - segmentProgress, 2);
          break;
        case 'step':
          alpha = Math.floor(segmentProgress * 4) / 4;
          break;
        default:
          alpha = 1 - segmentProgress;
      }

      ctx.globalAlpha = alpha * trailOpacity * intensity * persistence;
      
      // Placeholder: draw ghost positions
      const offset = (i - trailLength / 2) * 5;
      ctx.fillStyle = trailColor;
      ctx.fillRect(
        position.x + offset,
        position.y - 20,
        40,
        40
      );
    }

    ctx.restore();
    return { success: true };
  }

  // ==========================================================================
  // Emotion Effect Renderer
  // ==========================================================================

  private renderEmotion(
    context: RenderContext,
    effect: EmotionEffect,
    position: Point2D
  ): EffectRenderResult {
    const { ctx, time, deltaTime } = context;
    const {
      symbolType,
      symbolSize,
      symbolColor,
      symbolCount,
      positionVariation,
      animationType,
      animationDuration,
      intensity
    } = effect;

    const progress = (time % animationDuration) / animationDuration;

    ctx.save();
    ctx.globalAlpha = intensity;

    for (let i = 0; i < symbolCount; i++) {
      const symbolProgress = (progress + i / symbolCount) % 1;
      
      // Calculate position based on animation type
      let x = position.x + (Math.random() - 0.5) * positionVariation;
      let y = position.y;
      let scale = 1;
      let alpha = 1;

      switch (animationType) {
        case 'pop':
          scale = Math.sin(symbolProgress * Math.PI);
          alpha = 1 - symbolProgress;
          break;
        case 'float':
          y = position.y - symbolProgress * 50;
          alpha = 1 - symbolProgress;
          break;
        case 'bounce':
          y = position.y - Math.abs(Math.sin(symbolProgress * Math.PI * 2)) * 30;
          break;
        case 'shake':
          x += (Math.random() - 0.5) * 10;
          y += (Math.random() - 0.5) * 10;
          break;
        case 'pulse':
          scale = 1 + Math.sin(symbolProgress * Math.PI * 4) * 0.2;
          break;
        case 'spiral':
          const angle = symbolProgress * Math.PI * 4;
          x = position.x + Math.cos(angle) * 30 * symbolProgress;
          y = position.y + Math.sin(angle) * 30 * symbolProgress - symbolProgress * 50;
          alpha = 1 - symbolProgress;
          break;
      }

      ctx.globalAlpha = alpha * intensity;
      
      // Draw the symbol
      this.drawEmotionSymbol(ctx, symbolType, x, y, symbolSize * scale, symbolColor);
    }

    ctx.restore();
    return { success: true };
  }

  // ==========================================================================
  // Manga Panel Renderer
  // ==========================================================================

  private renderMangaPanel(
    context: RenderContext,
    effect: MangaPanelEffect,
    position: Poi_nt2D
  ): EffectRenderResult {
    const { ctx, width, height, time } = context;
    const {
      panelShape,
      size,
      borderWidth,
      borderColor,
      borderOpacity,
      backgroundFill,
      backgroundColor,
      backgroundOpacity,
      screenTone,
      _screenToneIntensity,
      _screenToneColor,
      _focusEffect,
      _focusPoint,
      _focusSize,
      focusFeather,
      vignetteIntensity,
      sfxText,
      sfxStyle,
      intensity
    } = effect;

    ctx.save();
    ctx.globalAlpha = intensity;

    // Draw panel background
    const panelX = position.x - size.width / 2;
    const panelY = position.y - size.height / 2;

    // Background
    if (backgroundFill !== 'transparent') {
      ctx.globalAlpha = backgroundOpacity * intensity;
      ctx.fillStyle = backgroundColor;
      
      // Draw shape based on panel shape
      switch (panelShape) {
        case 'rectangle':
          ctx.fillRect(panelX, panelY, size.width, size.height);
          break;
        case 'rounded':
          this.roundRect(ctx, panelX, panelY, size.width, size.height, 10);
          break;
        case 'jagged':
          this.drawJaggedRect(ctx, panelX, panelY, size.width, size.height);
          break;
        case 'burst':
          this.drawBurst(ctx, position.x, position.y, size.width / 2, 8, backgroundColor, backgroundOpacity);
          break;
      }
    }

    // Draw screen tone
    if (screenTone !== 'gradient') {
      ctx.globalAlpha = screenToneIntensity * intensity;
      this.drawScreenTone(ctx, panelX, panelY, size.width, size.height, screenTone, screenToneColor);
    }

    // Draw border
    ctx.globalAlpha = borderOpacity * intensity;
    ctx.strokeStyle = borderColor;
    ctx.lineWidth = borderWidth;

    switch (panelShape) {
      case 'rectangle':
        ctx.strokeRect(panelX, panelY, size.width, size.height);
        break;
      case 'rounded':
        this.roundRect(ctx, panelX, panelY, size.width, size.height, 10, false, true);
        break;
    }

    // Draw SFX text
    if (sfxText && sfxStyle) {
      ctx.globalAlpha = intensity;
      ctx.font = `${sfxStyle.fontWeight} ${sfxStyle.fontSize}px ${sfxStyle.fontFamily}`;
      ctx.fillStyle = sfxStyle.color;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      
      if (sfxStyle.outlineColor && sfxStyle.outlineWidth) {
        ctx.strokeStyle = sfxStyle.outlineColor;
        ctx.lineWidth = sfxStyle.outlineWidth;
        ctx.strokeText(sfxText, position.x, position.y);
      }
      
      ctx.fillText(sfxText, position.x, position.y);
    }

    ctx.restore();
    return { success: true };
  }

  // ==========================================================================
  // Aura Effect Renderer
  // ==========================================================================

  private renderAura(
    context: RenderContext,
    effect: AuraEffect,
    position: Point2D
  ): EffectRenderResult {
    co_nst { ctx, time } = context;
    const {
      auraType,
      color,
      secondaryColor,
      size,
      innerRadius,
      outerRadius,
      opacity,
      layers,
      layerOffset,
      animationSpeed,
      wobble,
      wobbleIntensity,
      pulse,
      pulseSpeed,
      pulseIntensity,
      intensity
    } = effect;

    const progress = (time * animationSpeed * 0.001) % 1;

    ctx.save();

    for (let layer = 0; layer < layers; layer++) {
      const layerProgress = (progress + layer * layerOffset) % 1;
      const layerAlpha = opacity * intensity * (1 - layer * 0.2);
      
      ctx.globalAlpha = layerAlpha;

      // Calculate radius with pulse
      let radius = innerRadius + (outerRadius - innerRadius) * layerProgress;
      if (pulse) {
        radius *= 1 + Math.sin(progress * Math.PI * 2 * pulseSpeed) * pulseIntensity;
      }

      // Add wobble
      let offsetX = 0, offsetY = 0;
      if (wobble) {
        offsetX = Math.sin(time * 0.003 + layer) * wobbleIntensity * 10;
        offsetY = Math.cos(time * 0.004 + layer) * wobbleIntensity * 10;
      }

      // Create gradient
      const gradient = ctx.createRadialGradient(
        position.x + offsetX,
        position.y + offsetY,
        0,
        position.x + offsetX,
        position.y + offsetY,
        radius * size * 50
      );

      gradient.addColorStop(0, color);
      gradient.addColorStop(0.5, secondaryColor || color);
      gradient.addColorStop(1, 'transparent');

      ctx.fillStyle = gradient;
      ctx.beginPath();
      ctx.arc(
        position.x + offsetX,
        position.y + offsetY,
        radius * size * 50,
        0,
        Math.PI * 2
      );
      ctx.fill();
    }

    ctx.restore();
    return { success: true };
  }

  // ==========================================================================
  // Helper Drawing Methods
  // ==========================================================================

  private drawStar(
    ctx: CanvasRenderingContext2D,
    cx: number, cy: number,
    points: number,
    outerRadius: number,
    innerRadius: number,
    color: string,
    alpha: number
  ): void {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.fillStyle = color;
    ctx.beginPath();

    for (let i = 0; i < points * 2; i++) {
      const radius = i % 2 === 0 ? outerRadius : innerRadius;
      const angle = (Math.PI * i) / points - Math.PI / 2;
      const x = cx + Math.cos(angle) * radius;
      const y = cy + Math.sin(angle) * radius;

      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    }

    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  private drawBurst(
    ctx: CanvasRenderingContext2D,
    cx: number, cy: number,
    size: number,
    points: number,
    color: string,
    alpha: number
  ): void {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.fillStyle = color;
    ctx.beginPath();

    for (let i = 0; i < points * 2; i++) {
      const radius = i % 2 === 0 ? size : size * 0.3;
      const angle = (Math.PI * 2 * i) / (points * 2);
      const x = cx + Math.cos(angle) * radius;
      const y = cy + Math.sin(angle) * radius;

      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    }

    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  private drawJaggedRect(
    ctx: CanvasRenderingContext2D,
    x: number, y: number,
    width: number, height: number
  ): void {
    const jaggedness = 5;
    ctx.beginPath();
    
    // Top edge
    for (let i = 0; i <= width; i += 10) {
      const jy = y + (Math.random() - 0.5) * jaggedness;
      if (i === 0) ctx.moveTo(x + i, jy);
      else ctx.lineTo(x + i, jy);
    }
    
    // Right edge
    for (let i = 0; i <= height; i += 10) {
      const jx = x + width + (Math.random() - 0.5) * jaggedness;
      ctx.lineTo(jx, y + i);
    }
    
    // Bottom edge
    for (let i = width; i >= 0; i -= 10) {
      const jy = y + height + (Math.random() - 0.5) * jaggedness;
      ctx.lineTo(x + i, jy);
    }
    
    // Left edge
    for (let i = height; i >= 0; i -= 10) {
      const jx = x + (Math.random() - 0.5) * jaggedness;
      ctx.lineTo(jx, y + i);
    }
    
    ctx.closePath();
    ctx.fill();
  }

  private roundRect(
    ctx: CanvasRenderingContext2D,
    x: number, y: number,
    width: number, height: number,
    radius: number,
    fill: boolean = true,
    stroke: boolean = false
  ): void {
    ctx.beginPath();
    ctx.moveTo(x + radius, y);
    ctx.lineTo(x + width - radius, y);
    ctx.quadraticCurveTo(x + width, y, x + width, y + radius);
    ctx.lineTo(x + width, y + height - radius);
    ctx.quadraticCurveTo(x + width, y + height, x + width - radius, y + height);
    ctx.lineTo(x + radius, y + height);
    ctx.quadraticCurveTo(x, y + height, x, y + height - radius);
    ctx.lineTo(x, y + radius);
    ctx.quadraticCurveTo(x, y, x + radius, y);
    ctx.closePath();
    
    if (fill) ctx.fill();
    if (stroke) ctx.stroke();
  }

  private drawScreenTone(
    ctx: CanvasRenderingContext2D,
    x: number, y: number,
    width: number, height: number,
    pattern: string,
    color: string
  ): void {
    ctx.save();
    ctx.fillStyle = color;

    switch (pattern) {
      case 'dots':
        const dotSpacing = 4;
        for (let dx = 0; dx < width; dx += dotSpacing) {
          for (let dy = 0; dy < height; dy += dotSpacing) {
            ctx.beginPath();
            ctx.arc(x + dx, y + dy, 1, 0, Math.PI * 2);
            ctx.fill();
          }
        }
        break;
      case 'lines':
        for (let dy = 0; dy < height; dy += 3) {
          ctx.fillRect(x, y + dy, width, 1);
        }
        break;
      case 'crosshatch':
        for (let d = 0; d < Math.max(width, height); d += 4) {
          ctx.fillRect(x + d, y, 1, height);
          ctx.fillRect(x, y + d, width, 1);
        }
        break;
    }

    ctx.restore();
  }

  private drawEmotionSymbol(
    ctx: CanvasRenderingContext2D,
    type: string,
    x: number, y: number,
    size: number,
    color: string
  ): void {
    ctx.save();
    ctx.fillStyle = color;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;

    switch (type) {
      case 'exclamation':
        ctx.fillRect(x - size * 0.15, y - size * 0.5, size * 0.3, size * 0.7);
        ctx.beginPath();
        ctx.arc(x, y + size * 0.35, size * 0.1, 0, Math.PI * 2);
        ctx.fill();
        break;

      case 'question':
        ctx.font = `${size}px Arial`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('?', x, y);
        break;

      case 'heart':
        ctx.font = `${size}px Arial`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('❤', x, y);
        break;

      case 'sparkle':
        this.drawStar(ctx, x, y, 4, size * 0.5, size * 0.25, color, 1);
        break;

      case 'sweat_drop':
        ctx.beginPath();
        ctx.moveTo(x, y - size * 0.3);
        ctx.quadraticCurveTo(x + size * 0.4, y, x, y + size * 0.4);
        ctx.quadraticCurveTo(x - size * 0.4, y, x, y - size * 0.3);
        ctx.fill();
        break;

      case 'anger_vein':
        ctx.beginPath();
        ctx.moveTo(x - size * 0.3, y);
        ctx.lineTo(x, y - size * 0.3);
        ctx.lineTo(x + size * 0.3, y);
        ctx.lineTo(x, y + size * 0.3);
        ctx.closePath();
        ctx.stroke();
        break;

      default:
        ctx.beginPath();
        ctx.arc(x, y, size * 0.3, 0, Math.PI * 2);
        ctx.fill();
    }

    ctx.restore();
  }

  private drawParticles(
    ctx: CanvasRenderingContext2D,
    effect: ImpactFrameEffect,
    cx: number, cy: number,
    time: number,
    progress: number
  ): void {
    const { particles } = effect;
    const count = particles.count;

    ctx.save();
    ctx.fillStyle = particles.color;

    for (let i = 0; i < count; i++) {
      const angle = (2 * Math.PI * i) / count + (particles.spreadAngle === 360 ? 0 : -Math.PI / 4);
      const speed = particles.speedRange[0] + Math.random() * (particles.speedRange[1] - particles.speedRange[0]);
      const size = particles.sizeRange[0] + Math.random() * (particles.sizeRange[1] - particles.sizeRange[0]);
      
      const distance = speed * progress;
      const x = cx + Math.cos(angle) * distance;
      const y = cy + Math.sin(angle) * distance + particles.gravity * progress * progress * 0.5;

      ctx.globalAlpha = 1 - progress;
      ctx.beginPath();
      ctx.arc(x, y, size, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  }
}

